            { "rb-duel-two-lines-one-road/beat/10", new[] { "One each?", "Eins zu eins?", "\u00bfUna para cada uno?", "Un partout ?", "Uno a testa?", "M\u1ed7i ng\u01b0\u1eddi m\u1ed9t \u0111i\u1ec3m \u00e0?" } },
            { "rb-duel-two-lines-one-road/beat/11", new[] { "We have not reached the second bend.", "Wir sind noch nicht mal an der zweiten Kurve.", "A\u00fan no hemos llegado a la segunda curva.", "On n'a pas encore atteint le deuxi\u00e8me virage.", "Non siamo ancora alla seconda curva.", "C\u00f2n ch\u01b0a t\u1edbi kh\u00fac cua th\u1ee9 hai m\u00e0." } },
            { "rb-duel-two-lines-one-road/beat/12", new[] { "A patch of gravel lies in the shadow.", "Im Schatten liegt ein Streifen Schotter.", "Hay una mancha de grava en la sombra.", "Une plaque de gravier se cache dans l'ombre.", "Una chiazza di ghiaia \u00e8 nascosta nell'ombra.", "M\u1ed9t m\u1ea3ng s\u1ecfi n\u1eb1m trong b\u00f3ng r\u00e2m." } },
            { "rb-duel-two-lines-one-road/beat/13", new[] { "I see it.", "Ich sehe ihn.", "La veo.", "Je la vois.", "La vedo.", "T\u00f4i th\u1ea5y r\u1ed3i." } },
            { "rb-duel-two-lines-one-road/beat/14", new[] { "They spread out before the narrow section.", "Vor der Engstelle vergr\u00f6\u00dfern sie den Abstand.", "Se separan antes del tramo estrecho.", "Ils s'\u00e9cartent avant la partie \u00e9troite.", "Si distanziano prima del tratto stretto.", "H\u1ecd gi\u00e3n kho\u1ea3ng c\u00e1ch tr\u01b0\u1edbc \u0111o\u1ea1n \u0111\u01b0\u1eddng h\u1eb9p." } },
            { "rb-duel-two-lines-one-road/beat/15", new[] { "Juno stays wide of the loose surface.", "Juno h\u00e4lt Abstand zum losen Untergrund.", "Juno se mantiene lejos del firme suelto.", "Juno reste loin de la surface meuble.", "Juno gira largo per evitare il fondo sdrucciolevole.", "Juno v\u00f2ng tr\u00e1nh ph\u1ea7n m\u1eb7t \u0111\u01b0\u1eddng \u0111\u1ea7y s\u1ecfi." } },
            { "rb-duel-two-lines-one-road/beat/16", new[] { "Ash gives up speed to keep a clean line.", "Ash nimmt Tempo raus, um die Linie sauber zu halten.", "Ash sacrifica velocidad para mantener una trazada limpia.", "Ash sacrifie de la vitesse pour garder une trajectoire propre.", "Ash rinuncia alla velocit\u00e0 per tenere una traiettoria pulita.", "Ash gi\u1ea3m t\u1ed1c \u0111\u1ec3 gi\u1eef \u0111\u01b0\u1eddng ch\u1ea1y g\u1ecdn." } },
            { "rb-duel-two-lines-one-road/beat/17", new[] { "The gap opens, then settles.", "Der Abstand w\u00e4chst und bleibt dann konstant.", "La distancia aumenta y luego se estabiliza.", "L'\u00e9cart se creuse, puis se stabilise.", "Il distacco aumenta, poi si stabilizza.", "Kho\u1ea3ng c\u00e1ch n\u1edbi ra r\u1ed3i \u1ed5n \u0111\u1ecbnh." } },
            { "rb-duel-two-lines-one-road/beat/18", new[] { "That was the right choice.", "Das war die richtige Entscheidung.", "Has elegido bien.", "C'\u00e9tait le bon choix.", "Era la scelta giusta.", "\u0110\u00f3 l\u00e0 quy\u1ebft \u0111\u1ecbnh \u0111\u00fang." } },
            { "rb-duel-two-lines-one-road/beat/19", new[] { "It did not look like the fast choice.", "Nach der schnellsten sah sie nicht aus.", "No parec\u00eda la opci\u00f3n m\u00e1s r\u00e1pida.", "\u00c7a ne semblait pas \u00eatre le plus rapide.", "Non sembrava quella pi\u00f9 veloce.", "Tr\u00f4ng ch\u1eb3ng gi\u1ed1ng quy\u1ebft \u0111\u1ecbnh nhanh nh\u1ea5t." } },
            { "rb-duel-two-lines-one-road/beat/2", new[] { "One clean run. No excuses.", "Eine saubere Fahrt. Keine Ausreden.", "Una pasada limpia. Sin excusas.", "Un passage propre. Pas d'excuses.", "Una corsa pulita. Niente scuse.", "M\u1ed9t l\u01b0\u1ee3t \u0111ua \u0111\u1eb9p. Kh\u00f4ng vi\u1ec7n c\u1edb." } },
            { "rb-duel-two-lines-one-road/beat/20", new[] { "Sometimes those are different.", "Das ist manchmal nicht dasselbe.", "A veces no son la misma.", "Parfois, ce n'est pas la m\u00eame chose.", "A volte non sono la stessa cosa.", "\u0110\u00f4i khi hai \u0111i\u1ec1u \u0111\u00f3 kh\u00e1c nhau." } },
            { "rb-duel-two-lines-one-road/beat/21", new[] { "The tower is past the next crest.", "Hinter der n\u00e4chsten Kuppe steht der Turm.", "La torre est\u00e1 despu\u00e9s del pr\u00f3ximo cambio de rasante.", "Le ch\u00e2teau d'eau est apr\u00e8s la prochaine cr\u00eate.", "La torre \u00e8 oltre il prossimo dosso.", "Th\u00e1p n\u01b0\u1edbc n\u1eb1m sau \u0111\u1ec9nh d\u1ed1c t\u1edbi." } },
            { "rb-duel-two-lines-one-road/beat/22", new[] { "Both bikes climb toward the last turn.", "Beide Motorr\u00e4der steigen zur letzten Kurve hinauf.", "Las dos motos ascienden hacia la \u00faltima curva.", "Les deux motos montent vers le dernier virage.", "Entrambe le moto salgono verso l'ultima curva.", "Hai chi\u1ebfc xe leo d\u1ed1c t\u1edbi kh\u00fac cua cu\u1ed1i." } },
            { "rb-duel-two-lines-one-road/beat/23", new[] { "Ash moves early and finds the apex.", "Ash lenkt fr\u00fch ein und trifft den Scheitelpunkt.", "Ash se coloca pronto y alcanza el v\u00e9rtice.", "Ash se place t\u00f4t et trouve le point de corde.", "Ash si muove in anticipo e trova il punto di corda.", "Ash chuy\u1ec3n h\u01b0\u1edbng s\u1edbm v\u00e0 ch\u1ea1m \u0111\u00fang \u0111\u1ec9nh cua." } },
            { "rb-duel-two-lines-one-road/beat/24", new[] { "Juno carries a little too much entry speed.", "Juno f\u00e4hrt etwas zu schnell in die Kurve.", "Juno entra con un poco de demasiada velocidad.", "Juno entre un peu trop vite.", "Juno entra con un po' troppa velocit\u00e0.", "Juno v\u00e0o cua h\u01a1i nhanh." } },
            { "rb-duel-two-lines-one-road/beat/25", new[] { "The rear tire skips at the shoulder.", "Am Seitenstreifen versetzt das Hinterrad.", "La rueda trasera da un salto junto al arc\u00e9n.", "Le pneu arri\u00e8re saute pr\u00e8s du bas-c\u00f4t\u00e9.", "La gomma posteriore saltella sul bordo della strada.", "B\u00e1nh sau n\u1ea3y tr\u01b0\u1ee3t \u1edf m\u00e9p \u0111\u01b0\u1eddng." } },
            { "rb-duel-two-lines-one-road/beat/26", new[] { "Ash hears the engine change.", "Ash h\u00f6rt, wie sich das Motorger\u00e4usch ver\u00e4ndert.", "Ash oye cambiar el motor.", "Ash entend le moteur changer de r\u00e9gime.", "Ash sente il motore cambiare tono.", "Ash nghe ti\u1ebfng \u0111\u1ed9ng c\u01a1 \u0111\u1ed5i kh\u00e1c." } },
            { "rb-duel-two-lines-one-road/beat/27", new[] { "You all right?", "Alles in Ordnung?", "\u00bfTodo bien?", "\u00c7a va ?", "Tutto bene?", "C\u1eadu \u1ed5n ch\u1ee9?" } },
            { "rb-duel-two-lines-one-road/beat/28", new[] { "All right. Give me a moment.", "Alles gut. Gib mir einen Moment.", "Todo bien. Dame un momento.", "\u00c7a va. Laisse-moi un instant.", "Tutto bene. Dammi un momento.", "\u1ed4n. Cho t\u00f4i m\u1ed9t ch\u00fat." } },
            { "rb-duel-two-lines-one-road/beat/29", new[] { "The finish waits beyond the tower.", "Hinter dem Turm wartet das Ziel.", "La meta espera al otro lado de la torre.", "L'arriv\u00e9e attend au-del\u00e0 du ch\u00e2teau d'eau.", "Il traguardo aspetta oltre la torre.", "V\u1ea1ch \u0111\u00edch v\u1eabn ch\u1edd b\u00ean kia th\u00e1p n\u01b0\u1edbc." } },
            { "rb-duel-two-lines-one-road/beat/3", new[] { "Three bends to the water tower.", "Drei Kurven bis zum Wasserturm.", "Tres curvas hasta la torre de agua.", "Trois virages jusqu'au ch\u00e2teau d'eau.", "Tre curve fino alla torre dell'acqua.", "Ba kh\u00fac cua t\u1edbi th\u00e1p n\u01b0\u1edbc." } },
            { "rb-duel-two-lines-one-road/beat/30", new[] { "You could have had it.", "Du h\u00e4ttest gewinnen k\u00f6nnen.", "Podr\u00edas haber ganado.", "Tu aurais pu gagner.", "Avresti potuto vincere.", "C\u1eadu \u0111\u00e3 c\u00f3 th\u1ec3 th\u1eafng r\u1ed3i." } },
            { "rb-duel-two-lines-one-road/beat/31", new[] { "I still want a proper answer.", "Ich will immer noch eine klare Antwort.", "A\u00fan quiero una respuesta de verdad.", "Je veux toujours une vraie r\u00e9ponse.", "Voglio ancora una risposta vera.", "T\u00f4i v\u1eabn mu\u1ed1n bi\u1ebft ai h\u01a1n ai cho \u0111\u00e0ng ho\u00e0ng." } },
            { "rb-duel-two-lines-one-road/beat/32", new[] { "Then another corner.", "Dann noch eine Kurve.", "Entonces, otra curva.", "Alors, encore un virage.", "Allora un'altra curva.", "V\u1eady th\u00eam m\u1ed9t kh\u00fac cua n\u1eefa." } },
            { "rb-duel-two-lines-one-road/beat/33", new[] { "They start together without a signal.", "Sie fahren ohne Zeichen gemeinsam los.", "Arrancan juntos, sin se\u00f1al.", "Ils repartent ensemble, sans signal.", "Ripartono insieme senza un segnale.", "H\u1ecd c\u00f9ng xu\u1ea5t ph\u00e1t m\u00e0 kh\u00f4ng c\u1ea7n ra hi\u1ec7u." } },
            { "rb-duel-two-lines-one-road/beat/34", new[] { "This time both riders leave room.", "Diesmal lassen beide einander Platz.", "Esta vez, ambos dejan espacio.", "Cette fois, les deux pilotes laissent de la place.", "Stavolta entrambi lasciano spazio.", "L\u1ea7n n\u00e0y c\u1ea3 hai \u0111\u1ec1u ch\u1eeba kho\u1ea3ng tr\u1ed1ng." } },
            { "rb-duel-two-lines-one-road/beat/35", new[] { "The tower passes between their shadows.", "Der Turm zieht zwischen ihren Schatten vorbei.", "La torre pasa entre sus sombras.", "Le ch\u00e2teau d'eau passe entre leurs ombres.", "La torre passa tra le loro ombre.", "Th\u00e1p n\u01b0\u1edbc l\u01b0\u1edbt qua gi\u1eefa hai b\u00f3ng xe." } },
            { "rb-duel-two-lines-one-road/beat/36", new[] { "Too close to call.", "Zu knapp f\u00fcr eine Entscheidung.", "Demasiado igualado para decidir.", "Trop serr\u00e9 pour trancher.", "Troppo vicini per decidere.", "S\u00e1t qu\u00e1, kh\u00f4ng ph\u00e2n \u0111\u01b0\u1ee3c." } },
            { "rb-duel-two-lines-one-road/beat/37", new[] { "That sounds like another ride.", "Das klingt nach einer weiteren Fahrt.", "Eso suena a otra salida.", "\u00c7a ressemble \u00e0 une prochaine sortie.", "Mi sa che ci vuole un altro giro.", "V\u1eady l\u00e0 ph\u1ea3i c\u00f3 th\u00eam m\u1ed9t chuy\u1ebfn n\u1eefa." } },
            { "rb-duel-two-lines-one-road/beat/38", new[] { "Next time, you take the outside.", "N\u00e4chstes Mal nimmst du die Au\u00dfenlinie.", "La pr\u00f3xima vez, t\u00fa vas por fuera.", "La prochaine fois, tu prends l'ext\u00e9rieur.", "La prossima volta prendi tu l'esterno.", "L\u1ea7n sau c\u1eadu \u00f4m ph\u00eda ngo\u00e0i nh\u00e9." } },
            { "rb-duel-two-lines-one-road/beat/39", new[] { "Next time, you try waiting.", "Und du versuchst es n\u00e4chstes Mal mit Warten.", "La pr\u00f3xima vez, t\u00fa pruebas a esperar.", "La prochaine fois, tu essaies d'attendre.", "La prossima volta prova tu ad aspettare.", "L\u1ea7n sau c\u1eadu th\u1eed ki\u00ean nh\u1eabn nh\u00e9." } },
            { "rb-duel-two-lines-one-road/beat/4", new[] { "The first bend rewards patience.", "Die erste Kurve belohnt Geduld.", "La primera curva premia la paciencia.", "Le premier virage r\u00e9compense la patience.", "La prima curva premia la pazienza.", "Kh\u00fac cua \u0111\u1ea7u d\u00e0nh ph\u1ea7n th\u01b0\u1edfng cho s\u1ef1 ki\u00ean nh\u1eabn." } },
            { "rb-duel-two-lines-one-road/beat/5", new[] { "Then I will try something new.", "Dann probiere ich mal etwas Neues.", "Entonces probar\u00e9 algo nuevo.", "Alors je vais essayer quelque chose de nouveau.", "Allora prover\u00f2 qualcosa di nuovo.", "V\u1eady t\u00f4i th\u1eed c\u00e1ch m\u1edbi xem." } },
            { "rb-duel-two-lines-one-road/beat/6", new[] { "They leave the shoulder together.", "Sie verlassen gemeinsam den Seitenstreifen.", "Salen juntos del arc\u00e9n.", "Ils quittent le bas-c\u00f4t\u00e9 ensemble.", "Lasciano la banchina insieme.", "C\u1ea3 hai c\u00f9ng r\u1eddi l\u1ec1 \u0111\u01b0\u1eddng." } },
            { "rb-duel-two-lines-one-road/beat/7", new[] { "Ash waits half a breath longer.", "Ash wartet einen halben Atemzug l\u00e4nger.", "Ash espera un instante m\u00e1s.", "Ash attend une demi-seconde de plus.", "Ash aspetta mezzo respiro in pi\u00f9.", "Ash \u0111\u1ee3i th\u00eam n\u1eeda nh\u1ecbp th\u1edf." } },
            { "rb-duel-two-lines-one-road/beat/8", new[] { "Juno finds daylight near the exit.", "Juno findet am Kurvenausgang eine L\u00fccke.", "Juno encuentra un hueco cerca de la salida.", "Juno trouve une ouverture pr\u00e8s de la sortie.", "Juno trova uno spiraglio vicino all'uscita.", "Juno t\u00ecm \u0111\u01b0\u1ee3c kho\u1ea3ng tr\u1ed1ng g\u1ea7n l\u1ed1i ra cua." } },
            { "rb-duel-two-lines-one-road/beat/9", new[] { "Neither has a clear advantage.", "Keiner hat einen klaren Vorsprung.", "Ninguno tiene una ventaja clara.", "Ni l'un ni l'autre n'a d'avantage net.", "Nessuno ha un vantaggio netto.", "Ch\u01b0a ai chi\u1ebfm \u01b0u th\u1ebf r\u00f5 r\u00e0ng." } },
            { "rb-duel-two-lines-one-road/synopsis", new[] { "A private rivalry develops through three trials, a mistake and a deliberate shared finish.", "Eine private Rivalit\u00e4t f\u00fchrt durch drei Pr\u00fcfungen, einen Fehler und einen bewusst gemeinsamen Zieleinlauf.", "Una rivalidad personal pasa por tres pruebas, un error y una llegada juntos por decisi\u00f3n propia.", "Une rivalit\u00e9 personnelle \u00e9volue au fil de trois \u00e9preuves, d'une erreur et d'une arriv\u00e9e ensemble, par choix.", "Una rivalit\u00e0 privata attraversa tre prove, un errore e la scelta di tagliare il traguardo insieme.", "Cu\u1ed9c so k\u00e8 tr\u1ea3i qua ba th\u1eed th\u00e1ch, m\u1ed9t sai l\u1ea7m v\u00e0 quy\u1ebft \u0111\u1ecbnh c\u00f9ng c\u00e1n \u0111\u00edch." } },
            { "rb-duel-two-lines-one-road/title", new[] { "Two lines, one road", "Zwei Linien, eine Stra\u00dfe", "Dos trazadas, una carretera", "Deux trajectoires, une route", "Due traiettorie, una strada", "Hai \u0111\u01b0\u1eddng ch\u1ea1y, m\u1ed9t con \u0111\u01b0\u1eddng" } },
            { "rb-finalwin-the-road-stays-open/beat/0", new[] { "The final marker slips behind the group.", "Die letzte Markierung bleibt hinter der Gruppe zur\u00fcck.", "El grupo deja atr\u00e1s el \u00faltimo hito.", "Le groupe laisse le dernier rep\u00e8re derri\u00e8re lui.", "L'ultimo segnale scivola alle spalle del gruppo.", "C\u1ed9t m\u1ed1c cu\u1ed1i c\u00f9ng l\u00f9i l\u1ea1i sau c\u1ea3 nh\u00f3m." } },
            { "rb-finalwin-the-road-stays-open/beat/1", new[] { "Nobody reaches for another lap time.", "Niemand jagt mehr einer Rundenzeit nach.", "Nadie busca otro tiempo por vuelta.", "Personne ne cherche un nouveau chrono.", "Nessuno cerca un altro tempo sul giro.", "Kh\u00f4ng ai v\u1ed9i b\u1ea5m gi\u1edd th\u00eam m\u1ed9t v\u00f2ng." } },
            { "rb-finalwin-the-road-stays-open/beat/10", new[] { "There is no final corner.", "Es gibt keine letzte Kurve.", "No hay una \u00faltima curva.", "Il n'y a pas de dernier virage.", "Non esiste un'ultima curva.", "Ch\u1eb3ng c\u00f3 kh\u00fac cua n\u00e0o l\u00e0 cu\u1ed1i c\u00f9ng." } },
            { "rb-finalwin-the-road-stays-open/beat/11", new[] { "Racing Bois. Thanks for riding with us.", "Racing Bois. Danke, dass du mit uns gefahren bist.", "Racing Bois. Gracias por rodar con nosotros.", "Racing Bois. Merci d'avoir roul\u00e9 avec nous.", "Racing Bois. Grazie per aver viaggiato con noi.", "Racing Bois. C\u1ea3m \u01a1n \u0111\u00e3 \u0111\u1ed3ng h\u00e0nh." } },
            { "rb-finalwin-the-road-stays-open/beat/2", new[] { "They leave space for the last rider.", "Sie lassen Platz f\u00fcr das letzte Motorrad.", "Dejan espacio para el \u00faltimo piloto.", "Ils laissent de la place au dernier pilote.", "Lasciano spazio all'ultimo pilota.", "H\u1ecd ch\u1eeba ch\u1ed7 cho ng\u01b0\u1eddi v\u1ec1 cu\u1ed1i." } },
            { "rb-finalwin-the-road-stays-open/beat/3", new[] { "Every engine is accounted for.", "Alle Maschinen sind da.", "No falta ning\u00fan motor.", "Tous les moteurs sont l\u00e0.", "Ci sono tutti i motori all'appello.", "Ti\u1ebfng m\u00e1y \u0111\u00e3 \u0111\u1ee7 c\u1ea3 r\u1ed3i." } },
            { "rb-finalwin-the-road-stays-open/beat/4", new[] { "That is all five routes.", "Das waren alle f\u00fcnf Strecken.", "Ya est\u00e1n las cinco rutas.", "Voil\u00e0 les cinq routes.", "E con questo sono cinque percorsi.", "V\u1eady l\u00e0 \u0111\u1ee7 c\u1ea3 n\u0103m tuy\u1ebfn \u0111\u01b0\u1eddng." } },
            { "rb-finalwin-the-road-stays-open/beat/5", new[] { "And enough stories for the winter.", "Und genug Geschichten f\u00fcr den Winter.", "Y hay historias para todo el invierno.", "Et assez d'histoires pour tout l'hiver.", "E abbastanza storie per tutto l'inverno.", "V\u00e0 \u0111\u1ee7 chuy\u1ec7n k\u1ec3 su\u1ed1t m\u00f9a \u0111\u00f4ng." } },
            { "rb-finalwin-the-road-stays-open/beat/6", new[] { "Keep a few for the next rider.", "Heb ein paar f\u00fcr die N\u00e4chsten auf.", "Guardad alguna para quien venga despu\u00e9s.", "Gardez-en quelques-unes pour le prochain pilote.", "Tienine qualcuna per chi arriver\u00e0 dopo.", "\u0110\u1ec3 d\u00e0nh v\u00e0i chuy\u1ec7n cho ng\u01b0\u1eddi \u0111\u1ebfn sau nh\u00e9." } },
            { "rb-finalwin-the-road-stays-open/beat/7", new[] { "The garage light is still on.", "In der Garage brennt noch Licht.", "La luz del garaje sigue encendida.", "La lumi\u00e8re du garage est encore allum\u00e9e.", "La luce del garage \u00e8 ancora accesa.", "\u0110\u00e8n gara v\u1eabn s\u00e1ng." } },
            { "rb-finalwin-the-road-stays-open/beat/8", new[] { "Tomorrow, an easy road?", "Morgen eine leichte Strecke?", "\u00bfMa\u00f1ana, una carretera tranquila?", "Demain, une route tranquille ?", "Domani, una strada facile?", "Ng\u00e0y mai ch\u1ecdn \u0111\u01b0\u1eddng d\u1ec5 th\u00f4i nh\u00e9?" } },
            { "rb-finalwin-the-road-stays-open/beat/9", new[] { "Tomorrow, a good one.", "Morgen eine gute.", "Ma\u00f1ana, una buena.", "Demain, une belle route.", "Domani, una bella strada.", "Ng\u00e0y mai ch\u1ecdn m\u1ed9t con \u0111\u01b0\u1eddng hay." } },
            { "rb-finalwin-the-road-stays-open/synopsis", new[] { "Finishing the campaign becomes a shared moment and a return to ordinary riding.", "Der Abschluss der Kampagne wird zu einem gemeinsamen Moment und einer R\u00fcckkehr zum einfachen Fahren.", "Terminar la campa\u00f1a se convierte en un momento compartido y una vuelta a rodar por placer.", "La fin de la campagne devient un moment partag\u00e9, puis un retour au simple plaisir de rouler.", "La fine della campagna diventa un momento da condividere e un ritorno alle uscite di tutti i giorni.", "Ho\u00e0n th\u00e0nh chi\u1ebfn d\u1ecbch tr\u1edf th\u00e0nh kho\u1ea3nh kh\u1eafc chung c\u1ee7a c\u1ea3 nh\u00f3m tr\u01b0\u1edbc khi tr\u1edf l\u1ea1i nh\u1eefng chuy\u1ebfn \u0111i th\u01b0\u1eddng ng\u00e0y." } },
            { "rb-finalwin-the-road-stays-open/title", new[] { "The road stays open", "Die Stra\u00dfe bleibt offen", "La carretera sigue abierta", "La route reste ouverte", "La strada resta aperta", "\u0110\u01b0\u1eddng v\u1eabn r\u1ed9ng m\u1edf" } },
            { "rb-intro-a-road-with-room/beat/0", new[] { "The garage opens before the city does.", "Die Garage \u00f6ffnet, bevor die Stadt erwacht.", "El garaje abre antes de que despierte la ciudad.", "Le garage ouvre avant que la ville se r\u00e9veille.", "Il garage apre prima che la citt\u00e0 si svegli.", "Gara m\u1edf c\u1eeda tr\u01b0\u1edbc khi th\u00e0nh ph\u1ed1 th\u1ee9c gi\u1ea5c." } },
            { "rb-intro-a-road-with-room/beat/1", new[] { "A worn map covers the workbench.", "Eine abgenutzte Karte liegt auf der Werkbank.", "Un mapa gastado cubre el banco de trabajo.", "Une carte us\u00e9e couvre l'\u00e9tabli.", "Una mappa consumata copre il banco da lavoro.", "T\u1ea5m b\u1ea3n \u0111\u1ed3 c\u0169 ph\u1ee7 k\u00edn b\u00e0n s\u1eeda xe." } },
            { "rb-intro-a-road-with-room/beat/10", new[] { "Ash waits until the last engine catches.", "Ash wartet, bis der letzte Motor anspringt.", "Ash espera a que arranque el \u00faltimo motor.", "Ash attend que le dernier moteur d\u00e9marre.", "Ash aspetta che si avvii anche l'ultimo motore.", "Ash ch\u1edd t\u1edbi khi \u0111\u1ed9ng c\u01a1 cu\u1ed1i c\u00f9ng n\u1ed5 m\u00e1y." } },
            { "rb-intro-a-road-with-room/beat/11", new[] { "Leave a little room for surprise.", "Lass etwas Platz f\u00fcr das Unerwartete.", "Deja un poco de espacio para las sorpresas.", "Garde un peu de place pour l'impr\u00e9vu.", "Lascia un po' di spazio agli imprevisti.", "Ch\u1eeba m\u1ed9t ch\u00fat kho\u1ea3ng tr\u1ed1ng cho \u0111i\u1ec1u b\u1ea5t ng\u1edd." } },
            { "rb-intro-a-road-with-room/beat/12", new[] { "The city gives way to open ground.", "Die Stadt weicht der offenen Landschaft.", "La ciudad da paso al campo abierto.", "La ville c\u00e8de la place aux grands espaces.", "La citt\u00e0 lascia il posto alla campagna aperta.", "Th\u00e0nh ph\u1ed1 l\u00f9i xa, kho\u1ea3ng tr\u1eddi r\u1ed9ng m\u1edf ra." } },
            { "rb-intro-a-road-with-room/beat/13", new[] { "The first bend asks a simple question.", "Die erste Kurve stellt eine einfache Frage.", "La primera curva plantea una pregunta sencilla.", "Le premier virage pose une question simple.", "La prima curva pone una domanda semplice.", "Kh\u00fac cua \u0111\u1ea7u \u0111\u1eb7t m\u1ed9t c\u00e2u h\u1ecfi \u0111\u01a1n gi\u1ea3n." } },
            { "rb-intro-a-road-with-room/beat/14", new[] { "Nobody answers it quite the same way.", "Niemand beantwortet sie ganz gleich.", "Nadie la responde exactamente igual.", "Personne n'y r\u00e9pond exactement de la m\u00eame fa\u00e7on.", "Nessuno risponde proprio allo stesso modo.", "Kh\u00f4ng ai tr\u1ea3 l\u1eddi ho\u00e0n to\u00e0n gi\u1ed1ng nhau." } },
            { "rb-intro-a-road-with-room/beat/15", new[] { "Racing Bois. Find your own line.", "Racing Bois. Finde deine eigene Linie.", "Racing Bois. Encuentra tu propia trazada.", "Racing Bois. Trouvez votre propre trajectoire.", "Racing Bois. Trova la tua traiettoria.", "Racing Bois. T\u00ecm \u0111\u01b0\u1eddng ch\u1ea1y c\u1ee7a ri\u00eang m\u00ecnh." } },
            { "rb-intro-a-road-with-room/beat/2", new[] { "You are early.", "Du bist fr\u00fch dran.", "Has llegado pronto.", "Tu es en avance.", "Sei in anticipo.", "C\u1eadu \u0111\u1ebfn s\u1edbm \u0111\u1ea5y." } },
            { "rb-intro-a-road-with-room/beat/3", new[] { "I did not want to miss the first ride.", "Ich wollte die erste Fahrt nicht verpassen.", "No quer\u00eda perderme la primera salida.", "Je ne voulais pas rater la premi\u00e8re sortie.", "Non volevo perdermi il primo giro.", "T\u00f4i kh\u00f4ng mu\u1ed1n l\u1ee1 chuy\u1ebfn \u0111\u1ea7u ti\u00ean." } },
            { "rb-intro-a-road-with-room/beat/4", new[] { "The first ride is mostly listening.", "Bei der ersten Fahrt geht es vor allem ums Zuh\u00f6ren.", "En la primera salida, sobre todo se escucha.", "Pour la premi\u00e8re sortie, on \u00e9coute surtout.", "Al primo giro si ascolta soprattutto.", "Chuy\u1ebfn \u0111\u1ea7u ch\u1ee7 y\u1ebfu l\u00e0 l\u1eafng nghe." } },
            { "rb-intro-a-road-with-room/beat/5", new[] { "A loose mirror is tightened by hand.", "Ein lockerer Spiegel wird von Hand festgezogen.", "Alguien aprieta a mano un retrovisor suelto.", "Un r\u00e9troviseur desserr\u00e9 est resserr\u00e9 \u00e0 la main.", "Uno specchietto allentato viene stretto a mano.", "Chi\u1ebfc g\u01b0\u01a1ng l\u1ecfng \u0111\u01b0\u1ee3c si\u1ebft l\u1ea1i b\u1eb1ng tay." } },
            { "rb-intro-a-road-with-room/beat/6", new[] { "What do I need to know?", "Was muss ich wissen?", "\u00bfQu\u00e9 tengo que saber?", "Qu'est-ce que je dois savoir ?", "Che cosa devo sapere?", "T\u00f4i c\u1ea7n bi\u1ebft nh\u1eefng g\u00ec?" } },
            { "rb-intro-a-road-with-room/beat/7", new[] { "Where you are going. Who is beside you.", "Wohin du f\u00e4hrst. Und wer neben dir ist.", "Ad\u00f3nde vas. Qui\u00e9n va a tu lado.", "O\u00f9 tu vas. Qui roule \u00e0 c\u00f4t\u00e9 de toi.", "Dove vai. Chi hai accanto.", "M\u00ecnh \u0111i \u0111\u00e2u. Ai \u0111ang ch\u1ea1y b\u00ean c\u1ea1nh." } },
            { "rb-intro-a-road-with-room/beat/8", new[] { "The crew rolls the bikes into the light.", "Die Gruppe schiebt die Motorr\u00e4der ins Licht.", "El grupo saca las motos a la luz.", "Le groupe pousse les motos vers la lumi\u00e8re.", "Il gruppo spinge le moto fuori, alla luce.", "C\u1ea3 nh\u00f3m d\u1eaft xe ra ngo\u00e0i \u00e1nh s\u00e1ng." } },
            { "rb-intro-a-road-with-room/beat/9", new[] { "Names first. Lap times later.", "Erst die Namen. Die Rundenzeiten kommen sp\u00e4ter.", "Primero los nombres. Los tiempos, despu\u00e9s.", "Les pr\u00e9noms d'abord. Les chronos apr\u00e8s.", "Prima i nomi. I tempi sul giro possono aspettare.", "Bi\u1ebft t\u00ean nhau tr\u01b0\u1edbc. Th\u00e0nh t\u00edch t\u00ednh sau." } },
            { "rb-intro-a-road-with-room/synopsis", new[] { "A newcomer joins a loose crew and chooses a first route.", "Ein Neuling schlie\u00dft sich einer lockeren Gruppe an und w\u00e4hlt die erste Strecke.", "Alguien nuevo se une a un grupo informal y elige su primera ruta.", "Un nouveau venu rejoint une bande informelle et choisit sa premi\u00e8re route.", "Un nuovo arrivato si unisce a un gruppo informale e sceglie il primo percorso.", "M\u1ed9t ng\u01b0\u1eddi m\u1edbi gia nh\u1eadp nh\u00f3m b\u1ea1n ch\u1ea1y xe v\u00e0 ch\u1ecdn tuy\u1ebfn \u0111\u01b0\u1eddng \u0111\u1ea7u ti\u00ean." } },
            { "rb-intro-a-road-with-room/title", new[] { "A road with room", "Eine Stra\u00dfe mit Platz", "Una carretera con sitio", "Une route o\u00f9 chacun a sa place", "Una strada per tutti", "Con \u0111\u01b0\u1eddng c\u00f2n ch\u1ed7" } },
            { "rb-level-a-line-beside-the-sea/beat/0", new[] { "You can see forever.", "Man kann endlos weit sehen.", "Se ve hasta el infinito.", "On voit \u00e0 perte de vue.", "Puoi vedere all'infinito.", "Nh\u00ecn xa m\u00e3i ch\u1eb3ng th\u1ea5y \u0111i\u1ec3m cu\u1ed1i." } },
            { "rb-level-a-line-beside-the-sea/beat/1", new[] { "Except behind that headland.", "Nur nicht hinter diese Landzunge.", "Salvo detr\u00e1s de ese cabo.", "Sauf derri\u00e8re ce cap.", "Tranne dietro quel promontorio.", "Tr\u1eeb ph\u00eda sau m\u0169i \u0111\u1ea5t kia." } },
            { "rb-level-a-line-beside-the-sea/beat/2", new[] { "I knew you would say that.", "Ich wusste, dass du das sagen w\u00fcrdest.", "Sab\u00eda que ibas a decir eso.", "Je savais que tu dirais \u00e7a.", "Sapevo che l'avresti detto.", "Bi\u1ebft ngay c\u1eadu s\u1ebd n\u00f3i v\u1eady." } },
            { "rb-level-a-line-beside-the-sea/beat/3", new[] { "Beautiful roads still need attention.", "Auch sch\u00f6ne Stra\u00dfen verlangen Aufmerksamkeit.", "Las carreteras bonitas tambi\u00e9n exigen atenci\u00f3n.", "Les belles routes demandent aussi de l'attention.", "Anche le belle strade richiedono attenzione.", "\u0110\u01b0\u1eddng \u0111\u1eb9p v\u1eabn c\u1ea7n ch\u00fa \u00fd." } },
            { "rb-level-a-line-beside-the-sea/beat/4", new[] { "Then let us give this one plenty.", "Dann schenken wir dieser besonders viel.", "Pues a esta vamos a prestarle mucha.", "Alors donnons-en beaucoup \u00e0 celle-ci.", "Allora diamogliene in abbondanza.", "V\u1eady m\u00ecnh ch\u00fa \u00fd th\u1eadt k\u1ef9 con \u0111\u01b0\u1eddng n\u00e0y nh\u00e9." } },
            { "rb-level-a-line-beside-the-sea/synopsis", new[] { "A coast route brings crosswinds and open views.", "Eine K\u00fcstenstrecke bringt Seitenwind und weite Ausblicke.", "Una ruta costera trae vientos laterales y vistas despejadas.", "Une route c\u00f4ti\u00e8re apporte des vents de travers et des vues d\u00e9gag\u00e9es.", "Il percorso costiero porta vento laterale e panorami aperti.", "Tuy\u1ebfn ven bi\u1ec3n mang \u0111\u1ebfn gi\u00f3 ngang v\u00e0 t\u1ea7m nh\u00ecn r\u1ed9ng m\u1edf." } },
            { "rb-level-a-line-beside-the-sea/title", new[] { "A line beside the sea", "Eine Linie am Meer", "Una trazada junto al mar", "Une trajectoire au bord de la mer", "Una traiettoria sul mare", "\u0110\u01b0\u1eddng ch\u1ea1y b\u00ean bi\u1ec3n" } },
            { "rb-level-above-the-weather/beat/0", new[] { "The air is colder up here.", "Hier oben ist die Luft k\u00e4lter.", "Aqu\u00ed arriba el aire es m\u00e1s fr\u00edo.", "L'air est plus froid ici.", "Quass\u00f9 l'aria \u00e8 pi\u00f9 fredda.", "Tr\u00ean n\u00e0y kh\u00f4ng kh\u00ed l\u1ea1nh h\u01a1n." } },
            { "rb-level-above-the-weather/beat/1", new[] { "And the bends arrive faster.", "Und die Kurven kommen schneller.", "Y las curvas llegan antes.", "Et les virages arrivent plus vite.", "E le curve arrivano prima.", "V\u00e0 c\u00e1c kh\u00fac cua \u0111\u1ebfn nhanh h\u01a1n." } },
            { "rb-level-above-the-weather/beat/2", new[] { "Watch what the mountain hides.", "Achte darauf, was der Berg verbirgt.", "F\u00edjate en lo que esconde la monta\u00f1a.", "Attention \u00e0 ce que la montagne cache.", "Attento a ci\u00f2 che nasconde la montagna.", "C\u1ea9n th\u1eadn v\u1edbi nh\u1eefng g\u00ec ng\u1ecdn n\u00fai che khu\u1ea5t." } },
            { "rb-level-above-the-weather/beat/3", new[] { "I will leave more room.", "Ich lasse mehr Platz.", "Dejar\u00e9 m\u00e1s espacio.", "Je laisserai plus de place.", "Lascer\u00f2 pi\u00f9 spazio.", "T\u00f4i s\u1ebd ch\u1eeba th\u00eam kho\u1ea3ng c\u00e1ch." } },
            { "rb-level-above-the-weather/beat/4", new[] { "For the road and each other.", "F\u00fcr die Stra\u00dfe und f\u00fcreinander.", "Para la carretera y para los dem\u00e1s.", "\u00c0 la route, et aux autres.", "Alla strada e agli altri.", "Cho con \u0111\u01b0\u1eddng v\u00e0 cho nhau." } },
            { "rb-level-above-the-weather/beat/5", new[] { "There is the next pass.", "Da ist der n\u00e4chste Pass.", "Ah\u00ed est\u00e1 el siguiente puerto.", "Voil\u00e0 le prochain col.", "Ecco il prossimo passo.", "\u0110\u00e8o ti\u1ebfp theo kia r\u1ed3i." } },
            { "rb-level-above-the-weather/synopsis", new[] { "Climbing into thin air changes the riders' perspective.", "Die Fahrt in d\u00fcnnere Luft ver\u00e4ndert den Blick der Gruppe.", "El ascenso al aire enrarecido cambia la perspectiva de los pilotos.", "La mont\u00e9e dans l'air rar\u00e9fi\u00e9 change le regard des pilotes.", "Salendo nell'aria rarefatta, i piloti cambiano prospettiva.", "C\u00e0ng l\u00ean cao, kh\u00f4ng kh\u00ed lo\u00e3ng d\u1ea7n v\u00e0 g\u00f3c nh\u00ecn c\u1ee7a nh\u1eefng ng\u01b0\u1eddi l\u00e1i c\u0169ng \u0111\u1ed5i kh\u00e1c." } },
            { "rb-level-above-the-weather/title", new[] { "Above the weather", "\u00dcber den Wolken", "Por encima de las nubes", "Au-dessus des nuages", "Sopra le nuvole", "Tr\u00ean t\u1ea7ng m\u00e2y" } },
            { "rb-level-beyond-the-last-stamp/beat/0", new[] { "Every box has a mark.", "In jedem K\u00e4stchen ist ein Zeichen.", "Todas las casillas tienen una marca.", "Chaque case est coch\u00e9e.", "Ogni casella ha il suo segno.", "\u00d4 n\u00e0o c\u0169ng c\u00f3 d\u1ea5u r\u1ed3i." } },
            { "rb-level-beyond-the-last-stamp/beat/1", new[] { "So what is left?", "Was bleibt dann noch?", "Entonces, \u00bfqu\u00e9 queda?", "Alors, que reste-t-il ?", "E allora che cosa resta?", "V\u1eady c\u00f2n g\u00ec n\u1eefa?" } },
            { "rb-level-beyond-the-last-stamp/beat/2", new[] { "All the things between the boxes.", "All die Dinge zwischen den K\u00e4stchen.", "Todo lo que hay entre las casillas.", "Tout ce qu'il y a entre les cases.", "Tutto quello che c'\u00e8 tra le caselle.", "T\u1ea5t c\u1ea3 nh\u1eefng \u0111i\u1ec1u n\u1eb1m gi\u1eefa c\u00e1c \u00f4 \u1ea5y." } },
            { "rb-level-beyond-the-last-stamp/beat/3", new[] { "A quieter morning. A cleaner corner.", "Ein ruhigerer Morgen. Eine sauberere Kurve.", "Una ma\u00f1ana m\u00e1s tranquila. Una curva m\u00e1s limpia.", "Un matin plus calme. Un virage plus propre.", "Una mattina pi\u00f9 calma. Una curva pi\u00f9 pulita.", "M\u1ed9t s\u1edbm mai y\u00ean h\u01a1n. M\u1ed9t kh\u00fac cua g\u1ecdn h\u01a1n." } },
            { "rb-level-beyond-the-last-stamp/beat/4", new[] { "A few people worth riding with.", "Ein paar Menschen, mit denen man gern f\u00e4hrt.", "Gente con la que merece la pena rodar.", "Quelques personnes avec qui il fait bon rouler.", "Qualche persona con cui vale la pena viaggiare.", "V\u00e0i ng\u01b0\u1eddi b\u1ea1n \u0111\u00e1ng c\u00f9ng \u0111i." } },
            { "rb-level-beyond-the-last-stamp/beat/5", new[] { "That should keep us busy.", "Das d\u00fcrfte uns besch\u00e4ftigen.", "Con eso estaremos ocupados.", "\u00c7a devrait nous occuper.", "Direi che avremo da fare.", "Th\u1ebf c\u0169ng \u0111\u1ee7 b\u1eadn r\u1ed3i." } },
            { "rb-level-beyond-the-last-stamp/synopsis", new[] { "A complete route card becomes an invitation to return.", "Eine vollst\u00e4ndige Streckenkarte wird zur Einladung, zur\u00fcckzukehren.", "Una ficha de ruta completa se convierte en una invitaci\u00f3n a volver.", "Une fiche de route compl\u00e8te devient une invitation \u00e0 revenir.", "Una scheda del percorso completa diventa un invito a tornare.", "T\u1ea5m th\u1ebb l\u1ed9 tr\u00ecnh \u0111\u00e3 ho\u00e0n t\u1ea5t tr\u1edf th\u00e0nh l\u1eddi m\u1eddi quay l\u1ea1i." } },
            { "rb-level-beyond-the-last-stamp/title", new[] { "Beyond the last stamp", "Hinter dem letzten Stempel", "Despu\u00e9s del \u00faltimo sello", "Apr\u00e8s le dernier tampon", "Oltre l'ultimo timbro", "Sau d\u1ea5u \u0111\u00f3ng cu\u1ed1i c\u00f9ng" } },
            { "rb-level-city-rhythm/beat/0", new[] { "More windows. More crossings.", "Mehr Fenster. Mehr Kreuzungen.", "M\u00e1s ventanas. M\u00e1s cruces.", "Plus de fen\u00eatres. Plus de croisements.", "Pi\u00f9 finestre. Pi\u00f9 incroci.", "Nhi\u1ec1u c\u1eeda s\u1ed5 h\u01a1n. Nhi\u1ec1u giao l\u1ed9 h\u01a1n." } },
            { "rb-level-city-rhythm/beat/1", new[] { "Less room for an old assumption.", "Weniger Platz f\u00fcr alte Annahmen.", "Menos margen para dar cosas por hechas.", "Moins de place pour les vieilles certitudes.", "Meno spazio per le vecchie certezze.", "Kh\u00f4ng c\u00f2n nhi\u1ec1u ch\u1ed7 cho nh\u1eefng suy \u0111o\u00e1n c\u0169." } },
            { "rb-level-city-rhythm/beat/2", new[] { "We learn the rhythm first.", "Wir lernen zuerst den Rhythmus.", "Primero aprendemos el ritmo.", "On apprend d'abord le rythme.", "Prima impariamo il ritmo.", "M\u00ecnh h\u1ecdc nh\u1ecbp \u0111i\u1ec7u n\u01a1i n\u00e0y tr\u01b0\u1edbc." } },
            { "rb-level-city-rhythm/beat/3", new[] { "Then find our place in it.", "Dann finden wir unseren Platz darin.", "Despu\u00e9s encontramos nuestro sitio.", "Puis on y trouve notre place.", "Poi troviamo il nostro posto.", "R\u1ed3i t\u00ecm v\u1ecb tr\u00ed c\u1ee7a m\u00ecnh trong \u0111\u00f3." } },
            { "rb-level-city-rhythm/beat/4", new[] { "Welcome to the district.", "Willkommen im Bezirk.", "Bienvenidos al distrito.", "Bienvenue dans le district.", "Benvenuti nel distretto.", "Ch\u00e0o m\u1eebng t\u1edbi khu ph\u1ed1 m\u1edbi." } },
            { "rb-level-city-rhythm/synopsis", new[] { "A new route calls for different judgment.", "Eine neue Strecke verlangt anderes Urteilsverm\u00f6gen.", "Una nueva ruta exige otro criterio.", "Une nouvelle route demande un autre jugement.", "Un nuovo percorso richiede un modo diverso di valutare la strada.", "Tuy\u1ebfn \u0111\u01b0\u1eddng m\u1edbi \u0111\u00f2i h\u1ecfi c\u00e1ch ph\u00e1n \u0111o\u00e1n kh\u00e1c." } },
            { "rb-level-city-rhythm/title", new[] { "City rhythm", "Der Rhythmus der Stadt", "El ritmo de la ciudad", "Le rythme de la ville", "Il ritmo della citt\u00e0", "Nh\u1ecbp \u0111i\u1ec7u ph\u1ed1" } },
            { "rb-level-orchard-light/beat/0", new[] { "It smells different here.", "Hier riecht es anders.", "Aqu\u00ed huele distinto.", "L'odeur est diff\u00e9rente ici.", "Qui c'\u00e8 un odore diverso.", "M\u00f9i h\u01b0\u01a1ng \u1edf \u0111\u00e2y kh\u00e1c th\u1eadt." } },
            { "rb-level-orchard-light/beat/1", new[] { "Fruit, dust, and somebody's supper.", "Nach Obst, Staub und jemandes Abendessen.", "A fruta, polvo y la cena de alguien.", "Des fruits, de la poussi\u00e8re et le d\u00eener de quelqu'un.", "Frutta, polvere e la cena di qualcuno.", "M\u00f9i tr\u00e1i c\u00e2y, b\u1ee5i \u0111\u1ea5t v\u00e0 b\u1eefa t\u1ed1i nh\u00e0 ai \u0111\u00f3." } },
            { "rb-level-orchard-light/beat/2", new[] { "Leave the farm gates clear.", "Haltet die Hoftore frei.", "Deja libres las entradas de las fincas.", "Laisse les entr\u00e9es des fermes d\u00e9gag\u00e9es.", "Lasciate liberi i cancelli delle fattorie.", "\u0110\u1eebng ch\u1eafn c\u1ed5ng n\u00f4ng tr\u1ea1i." } },
            { "rb-level-orchard-light/beat/3", new[] { "We are guests on this road.", "Auf dieser Stra\u00dfe sind wir G\u00e4ste.", "Somos invitados en esta carretera.", "Nous sommes des invit\u00e9s sur cette route.", "Su questa strada siamo ospiti.", "M\u00ecnh l\u00e0 kh\u00e1ch tr\u00ean con \u0111\u01b0\u1eddng n\u00e0y." } },
            { "rb-level-orchard-light/beat/4", new[] { "Let us act like it.", "Dann benehmen wir uns auch so.", "Comport\u00e9monos como tales.", "Comportons-nous comme tels.", "Comportiamoci come tali.", "V\u1eady h\u00e3y c\u01b0 x\u1eed nh\u01b0 kh\u00e1ch." } },
            { "rb-level-orchard-light/synopsis", new[] { "A familiar skill meets a quieter landscape.", "Vertrautes K\u00f6nnen trifft auf eine ruhigere Landschaft.", "Una habilidad conocida se encuentra con un paisaje m\u00e1s tranquilo.", "Un savoir-faire familier rencontre un paysage plus paisible.", "Un'abilit\u00e0 ormai familiare incontra un paesaggio pi\u00f9 tranquillo.", "K\u1ef9 n\u0103ng quen thu\u1ed9c g\u1eb7p m\u1ed9t mi\u1ec1n phong c\u1ea3nh y\u00ean b\u00ecnh h\u01a1n." } },
            { "rb-level-orchard-light/title", new[] { "Orchard light", "Licht in den Obstg\u00e4rten", "Luz entre frutales", "La lumi\u00e8re du verger", "La luce del frutteto", "N\u1eafng v\u01b0\u1eddn c\u00e2y" } },
            { "rb-level-past-the-first-ridge/beat/0", new[] { "The old road looks smaller from here.", "Von hier sieht die alte Stra\u00dfe kleiner aus.", "Desde aqu\u00ed, la vieja carretera parece m\u00e1s peque\u00f1a.", "L'ancienne route para\u00eet plus petite d'ici.", "Da qui la vecchia strada sembra pi\u00f9 piccola.", "T\u1eeb \u0111\u00e2y nh\u00ecn l\u1ea1i, con \u0111\u01b0\u1eddng c\u0169 nh\u1ecf h\u1eb3n." } },
            { "rb-level-past-the-first-ridge/beat/1", new[] { "It did its job.", "Sie hat ihren Zweck erf\u00fcllt.", "Ha cumplido su funci\u00f3n.", "Elle a rempli son r\u00f4le.", "Ha fatto il suo dovere.", "N\u00f3 \u0111\u00e3 l\u00e0m tr\u00f2n nhi\u1ec7m v\u1ee5 r\u1ed3i." } },
            { "rb-level-past-the-first-ridge/beat/2", new[] { "There is a whole district past that ridge.", "Hinter diesem H\u00f6henzug liegt ein ganzer Bezirk.", "Detr\u00e1s de esa cresta hay todo un distrito.", "Il y a tout un district derri\u00e8re cette cr\u00eate.", "Oltre quel crinale c'\u00e8 un intero distretto.", "Sau r\u1eb7ng \u0111\u1ed3i kia l\u00e0 c\u1ea3 m\u1ed9t v\u00f9ng r\u1ed9ng l\u1edbn." } },
            { "rb-level-past-the-first-ridge/beat/3", new[] { "And more people who know its corners.", "Und noch mehr Leute, die seine Kurven kennen.", "Y m\u00e1s gente que conoce sus curvas.", "Et d'autres gens qui en connaissent les virages.", "E altra gente che ne conosce le curve.", "V\u00e0 nhi\u1ec1u ng\u01b0\u1eddi hi\u1ec3u t\u1eebng kh\u00fac cua \u1edf \u0111\u00f3." } },
            { "rb-level-past-the-first-ridge/beat/4", new[] { "We will listen before we race.", "Wir h\u00f6ren erst zu, bevor wir Rennen fahren.", "Escucharemos antes de correr.", "On \u00e9coutera avant de courir.", "Ascolteremo prima di correre.", "M\u00ecnh s\u1ebd l\u1eafng nghe tr\u01b0\u1edbc khi \u0111ua." } },
            { "rb-level-past-the-first-ridge/beat/5", new[] { "Pack light.", "Nimm nicht zu viel mit.", "Lleva poco equipaje.", "Voyage l\u00e9ger.", "Bagagli leggeri.", "Mang h\u00e0nh l\u00fd g\u1ecdn th\u00f4i." } },
            { "rb-level-past-the-first-ridge/beat/6", new[] { "Keep the good habits.", "Behalte die guten Gewohnheiten.", "Conserva las buenas costumbres.", "Garde les bonnes habitudes.", "Teniamoci le buone abitudini.", "Gi\u1eef l\u1ea5y nh\u1eefng th\u00f3i quen t\u1ed1t." } },
            { "rb-level-past-the-first-ridge/synopsis", new[] { "The group sees a larger world after the first milestone.", "Nach dem ersten Meilenstein entdeckt die Gruppe eine gr\u00f6\u00dfere Welt.", "Tras el primer hito, el grupo descubre un mundo m\u00e1s grande.", "Apr\u00e8s le premier jalon, le groupe d\u00e9couvre un monde plus vaste.", "Dopo il primo traguardo, il gruppo scopre un mondo pi\u00f9 grande.", "Sau c\u1ed9t m\u1ed1c \u0111\u1ea7u, c\u1ea3 nh\u00f3m nh\u00ecn th\u1ea5y m\u1ed9t th\u1ebf gi\u1edbi r\u1ed9ng l\u1edbn h\u01a1n." } },
            { "rb-level-past-the-first-ridge/title", new[] { "Past the first ridge", "Hinter dem ersten H\u00f6henzug", "M\u00e1s all\u00e1 de la primera cresta", "Au-del\u00e0 de la premi\u00e8re cr\u00eate", "Oltre il primo crinale", "Qua r\u1eb7ng \u0111\u1ed3i \u0111\u1ea7u ti\u00ean" } },
            { "rb-lose-a-better-question/beat/0", new[] { "I had more speed.", "Ich war schneller.", "Yo llevaba m\u00e1s velocidad.", "J'avais plus de vitesse.", "Avevo pi\u00f9 velocit\u00e0.", "T\u00f4i c\u00f3 t\u1ed1c \u0111\u1ed9 t\u1ed1t h\u01a1n." } },
            { "rb-lose-a-better-question/beat/1", new[] { "At the wrong time.", "Zum falschen Zeitpunkt.", "En el momento equivocado.", "Au mauvais moment.", "Nel momento sbagliato.", "Nh\u01b0ng kh\u00f4ng \u0111\u00fang l\u00fac." } },
            { "rb-lose-a-better-question/beat/2", new[] { "Where should I have waited?", "Wo h\u00e4tte ich warten sollen?", "\u00bfD\u00f3nde deber\u00eda haber esperado?", "O\u00f9 aurais-je d\u00fb attendre ?", "Dove avrei dovuto aspettare?", "L\u1ebd ra t\u00f4i n\u00ean ch\u1edd \u1edf \u0111\u00e2u?" } },
            { "rb-lose-a-better-question/beat/3", new[] { "Before the road made the choice for you.", "Bevor die Stra\u00dfe dir die Entscheidung abgenommen hat.", "Antes de que la carretera decidiera por ti.", "Avant que la route choisisse \u00e0 ta place.", "Prima che la strada decidesse per te.", "Tr\u01b0\u1edbc khi con \u0111\u01b0\u1eddng quy\u1ebft \u0111\u1ecbnh thay c\u1eadu." } },
            { "rb-lose-a-better-question/beat/4", new[] { "Show me again.", "Zeig es mir noch mal.", "Ens\u00e9\u00f1amelo otra vez.", "Montre-moi encore.", "Fammelo vedere ancora.", "Ch\u1ec9 l\u1ea1i cho t\u00f4i nh\u00e9." } },
            { "rb-lose-a-better-question/synopsis", new[] { "The rider replaces an excuse with a useful question.", "Statt einer Ausrede findet der Fahrer eine hilfreiche Frage.", "El piloto cambia una excusa por una pregunta \u00fatil.", "Le pilote remplace une excuse par une question utile.", "Il pilota sostituisce una scusa con una domanda utile.", "Thay v\u00ec vi\u1ec7n c\u1edb, ng\u01b0\u1eddi l\u00e1i \u0111\u1eb7t m\u1ed9t c\u00e2u h\u1ecfi h\u1eefu \u00edch." } },
            { "rb-lose-a-better-question/title", new[] { "A better question", "Die bessere Frage", "Una pregunta mejor", "Une meilleure question", "Una domanda migliore", "M\u1ed9t c\u00e2u h\u1ecfi hay h\u01a1n" } },
            { "rb-lose-a-cool-engine/beat/0", new[] { "It felt slower every mile.", "Sie wurde mit jedem Kilometer langsamer.", "Cada kil\u00f3metro parec\u00eda ir m\u00e1s despacio.", "Elle semblait ralentir \u00e0 chaque kilom\u00e8tre.", "Sembrava pi\u00f9 lenta a ogni chilometro.", "C\u00e0ng ch\u1ea1y c\u00e0ng th\u1ea5y ch\u1eadm \u0111i." } },
            { "rb-lose-a-cool-engine/beat/1", new[] { "Listen to it before you ask for more.", "H\u00f6r ihr zu, bevor du mehr verlangst.", "Esc\u00fachala antes de pedirle m\u00e1s.", "\u00c9coute-la avant de lui en demander plus.", "Ascoltala prima di chiederle altro.", "Nghe n\u00f3 tr\u01b0\u1edbc khi \u0111\u00f2i h\u1ecfi th\u00eam." } },
            { "rb-lose-a-cool-engine/beat/2", new[] { "You earned a rest, little bike.", "Eine Pause hast du dir verdient, kleine Maschine.", "Te has ganado un descanso, peque\u00f1a.", "Tu as m\u00e9rit\u00e9 une pause, petite moto.", "Ti sei guadagnata un po' di riposo, piccola moto.", "M\u00e0y x\u1ee9ng \u0111\u00e1ng \u0111\u01b0\u1ee3c ngh\u1ec9 r\u1ed3i, xe nh\u1ecf \u1ea1." } },
            { "rb-lose-a-cool-engine/beat/3", new[] { "So did you.", "Du auch.", "T\u00fa tambi\u00e9n.", "Toi aussi.", "Anche tu.", "C\u1eadu c\u0169ng v\u1eady." } },
            { "rb-lose-a-cool-engine/beat/4", new[] { "We both needed to hear that.", "Das mussten wir wohl beide h\u00f6ren.", "Nos hac\u00eda falta o\u00edrlo a los dos.", "On avait tous les deux besoin de l'entendre.", "Avevamo entrambi bisogno di sentirlo.", "C\u1ea3 hai \u0111\u1ec1u c\u1ea7n nghe c\u00e2u \u0111\u00f3." } },
            { "rb-lose-a-cool-engine/synopsis", new[] { "The rider learns to stop pushing a tired machine.", "Der Fahrer lernt, einer m\u00fcden Maschine nicht immer mehr abzuverlangen.", "El piloto aprende a no exigir m\u00e1s a una m\u00e1quina cansada.", "Le pilote apprend \u00e0 ne plus pousser une machine fatigu\u00e9e.", "Il pilota impara a non chiedere troppo a una moto stanca.", "Ng\u01b0\u1eddi l\u00e1i h\u1ecdc c\u00e1ch th\u00f4i th\u00fac \u00e9p m\u1ed9t c\u1ed7 m\u00e1y \u0111\u00e3 m\u1ec7t." } },
            { "rb-lose-a-cool-engine/title", new[] { "A cool engine", "Ein k\u00fchler Motor", "Un motor fr\u00edo", "Un moteur froid", "Un motore che si raffredda", "\u0110\u1ed9ng c\u01a1 ngu\u1ed9i d\u1ea7n" } },
            { "rb-lose-a-finish-worth-keeping/beat/0", new[] { "You stayed with it all the way.", "Du bist bis zum Schluss drangeblieben.", "Has seguido hasta el final.", "Tu as tenu jusqu'au bout.", "Hai tenuto duro fino alla fine.", "C\u1eadu \u0111\u00e3 theo t\u1edbi t\u1eadn cu\u1ed1i." } },
            { "rb-lose-a-finish-worth-keeping/beat/1", new[] { "It did not feel like enough.", "Es kam mir trotzdem zu wenig vor.", "No me parec\u00eda suficiente.", "\u00c7a ne me semblait pas suffisant.", "Non mi \u00e8 sembrato abbastanza.", "T\u00f4i v\u1eabn th\u1ea5y ch\u01b0a \u0111\u1ee7." } },
            { "rb-lose-a-finish-worth-keeping/beat/2", new[] { "Yesterday you would have turned back.", "Gestern w\u00e4rst du noch umgekehrt.", "Ayer habr\u00edas dado la vuelta.", "Hier, tu aurais fait demi-tour.", "Ieri saresti tornato indietro.", "H\u00f4m qua c\u1eadu \u0111\u00e3 quay v\u1ec1 gi\u1eefa ch\u1eebng r\u1ed3i." } },
            { "rb-lose-a-finish-worth-keeping/beat/3", new[] { "Yesterday had an easier hill.", "Gestern war der H\u00fcgel auch leichter.", "Ayer la cuesta era m\u00e1s f\u00e1cil.", "Hier, la mont\u00e9e \u00e9tait plus facile.", "Ieri la salita era pi\u00f9 facile.", "D\u1ed1c h\u00f4m qua d\u1ec5 h\u01a1n m\u00e0." } },
            { "rb-lose-a-finish-worth-keeping/beat/4", new[] { "And today had a steadier rider.", "Und heute warst du sicherer im Sattel.", "Y hoy el piloto era m\u00e1s constante.", "Et aujourd'hui, le pilote \u00e9tait plus r\u00e9gulier.", "E oggi il pilota era pi\u00f9 sicuro.", "Nh\u01b0ng tay l\u00e1i h\u00f4m nay v\u1eefng h\u01a1n." } },
            { "rb-lose-a-finish-worth-keeping/beat/5", new[] { "Keep today's line in your head.", "Merk dir deine Linie von heute.", "Qu\u00e9date con la trazada de hoy.", "Garde la trajectoire d'aujourd'hui en t\u00eate.", "Tieni a mente la traiettoria di oggi.", "Ghi nh\u1edb \u0111\u01b0\u1eddng ch\u1ea1y h\u00f4m nay nh\u00e9." } },
            { "rb-lose-a-finish-worth-keeping/beat/6", new[] { "We will build on it.", "Darauf bauen wir auf.", "A partir de ah\u00ed, mejoraremos.", "On va construire l\u00e0-dessus.", "Ripartiremo da l\u00ec.", "M\u00ecnh s\u1ebd ti\u1ebfn b\u1ed9 t\u1eeb \u0111\u00f3." } },
            { "rb-lose-a-finish-worth-keeping/synopsis", new[] { "A difficult run becomes a foundation for future practice.", "Eine schwierige Fahrt wird zur Grundlage f\u00fcrs weitere Training.", "Una pasada dif\u00edcil se convierte en la base de la pr\u00e1ctica futura.", "Un passage difficile devient une base pour les prochains entra\u00eenements.", "Una corsa difficile diventa la base per gli allenamenti futuri.", "L\u01b0\u1ee3t ch\u1ea1y kh\u00f3 tr\u1edf th\u00e0nh n\u1ec1n t\u1ea3ng cho nh\u1eefng l\u1ea7n t\u1eadp sau." } },
            { "rb-lose-a-finish-worth-keeping/title", new[] { "A finish worth keeping", "Ein Ziel, das bleibt", "Una llegada que merece recordarse", "Une arriv\u00e9e \u00e0 retenir", "Un arrivo da ricordare", "M\u1ed9t l\u1ea7n v\u1ec1 \u0111\u00edch \u0111\u00e1ng nh\u1edb" } },
            { "rb-lose-a-mirror-lesson/beat/0", new[] { "I kept checking your headlight.", "Ich habe st\u00e4ndig nach deinem Scheinwerfer gesehen.", "No dejaba de mirar tu faro.", "Je n'arr\u00eatais pas de regarder ton phare.", "Continuavo a controllare il tuo faro.", "T\u00f4i c\u1ee9 nh\u00ecn \u0111\u00e8n pha c\u1ee7a c\u1eadu." } },
            { "rb-lose-a-mirror-lesson/beat/1", new[] { "Mine was not the road.", "Mein Scheinwerfer zeigt dir nicht die Stra\u00dfe.", "Mi faro no era la carretera.", "Mon phare n'\u00e9tait pas la route.", "Il mio faro non era la strada.", "\u0110\u00e8n c\u1ee7a t\u00f4i \u0111\u00e2u ph\u1ea3i con \u0111\u01b0\u1eddng." } },
            { "rb-lose-a-mirror-lesson/beat/2", new[] { "Fair point.", "Da hast du recht.", "Tienes raz\u00f3n.", "C'est vrai.", "Hai ragione.", "C\u00f3 l\u00fd." } },
            { "rb-lose-a-mirror-lesson/beat/3", new[] { "Find the exit first.", "Such zuerst den Kurvenausgang.", "Primero busca la salida.", "Trouve d'abord la sortie.", "Prima trova l'uscita.", "T\u00ecm l\u1ed1i ra cua tr\u01b0\u1edbc." } },
            { "rb-lose-a-mirror-lesson/beat/4", new[] { "Mirror second.", "Dann kommt der Spiegel.", "Despu\u00e9s, el retrovisor.", "Le r\u00e9tro ensuite.", "Poi lo specchietto.", "R\u1ed3i m\u1edbi nh\u00ecn g\u01b0\u01a1ng." } },
            { "rb-lose-a-mirror-lesson/synopsis", new[] { "Watching behind made the rider miss what was ahead.", "Der Blick nach hinten lie\u00df den Fahrer \u00fcbersehen, was vor ihm lag.", "Por mirar atr\u00e1s, el piloto no vio lo que ten\u00eda delante.", "\u00c0 force de regarder derri\u00e8re, le pilote a manqu\u00e9 ce qui \u00e9tait devant.", "Guardando indietro, il pilota perde di vista ci\u00f2 che ha davanti.", "M\u1ea3i nh\u00ecn ph\u00eda sau khi\u1ebfn ng\u01b0\u1eddi l\u00e1i b\u1ecf l\u1ee1 \u0111i\u1ec1u \u1edf ph\u00eda tr\u01b0\u1edbc." } },
            { "rb-lose-a-mirror-lesson/title", new[] { "A mirror lesson", "Eine Lektion im R\u00fcckspiegel", "Una lecci\u00f3n de retrovisor", "Une le\u00e7on de r\u00e9troviseur", "Una lezione allo specchio", "B\u00e0i h\u1ecdc t\u1eeb chi\u1ebfc g\u01b0\u01a1ng" } },
            { "rb-lose-no-shortcut-home/beat/0", new[] { "Service road back?", "\u00dcber die Nebenstra\u00dfe zur\u00fcck?", "\u00bfVolvemos por la v\u00eda de servicio?", "On rentre par la voie de service ?", "Torniamo dalla strada di servizio?", "V\u1ec1 theo \u0111\u01b0\u1eddng ph\u1ee5 nh\u00e9?" } },
            { "rb-lose-no-shortcut-home/beat/1", new[] { "No. The ridge again.", "Nein. Noch mal \u00fcber den H\u00f6henzug.", "No. Por la cresta otra vez.", "Non. Encore la cr\u00eate.", "No. Di nuovo sul crinale.", "Kh\u00f4ng. L\u00ean \u0111\u1ed3i l\u1ea7n n\u1eefa." } },
            { "rb-lose-no-shortcut-home/beat/2", new[] { "Even now?", "Auch jetzt noch?", "\u00bfIncluso ahora?", "M\u00eame maintenant ?", "Anche adesso?", "Ngay b\u00e2y gi\u1edd sao?" } },
            { "rb-lose-no-shortcut-home/beat/3", new[] { "Especially now.", "Gerade jetzt.", "Sobre todo ahora.", "Surtout maintenant.", "Soprattutto adesso.", "Ch\u00ednh l\u00fac n\u00e0y m\u1edbi c\u1ea7n." } },
            { "rb-lose-no-shortcut-home/beat/4", new[] { "I will follow at an easier pace.", "Ich folge dir in ruhigerem Tempo.", "Te seguir\u00e9 a un ritmo m\u00e1s tranquilo.", "Je suivrai plus tranquillement.", "Ti seguir\u00f2 con pi\u00f9 calma.", "T\u00f4i s\u1ebd ch\u1ea1y ch\u1eadm h\u01a1n theo sau." } },
            { "rb-lose-no-shortcut-home/synopsis", new[] { "The rider chooses to practice the difficult section.", "Der Fahrer entscheidet sich, die schwierige Passage zu \u00fcben.", "El piloto decide practicar el tramo dif\u00edcil.", "Le pilote choisit de s'entra\u00eener sur le passage difficile.", "Il pilota sceglie di allenarsi sul tratto difficile.", "Ng\u01b0\u1eddi l\u00e1i ch\u1ecdn t\u1eadp l\u1ea1i \u0111o\u1ea1n \u0111\u01b0\u1eddng kh\u00f3." } },
            { "rb-lose-no-shortcut-home/title", new[] { "No shortcut home", "Keine Abk\u00fcrzung nach Hause", "Sin atajos de vuelta a casa", "Pas de raccourci pour rentrer", "Niente scorciatoie per casa", "Kh\u00f4ng \u0111i t\u1eaft v\u1ec1 nh\u00e0" } },
            { "rb-lose-not-the-whole-story/beat/0", new[] { "Nothing went right.", "Nichts ist gut gelaufen.", "Nada ha salido bien.", "Rien ne s'est bien pass\u00e9.", "Non \u00e8 andato bene niente.", "Ch\u1eb3ng c\u00f3 g\u00ec su\u00f4n s\u1ebb c\u1ea3." } },
            { "rb-lose-not-the-whole-story/beat/1", new[] { "You gave that stopped car room.", "Du hast dem stehenden Auto Platz gelassen.", "Le has dejado espacio a ese coche parado.", "Tu as laiss\u00e9 de la place \u00e0 cette voiture arr\u00eat\u00e9e.", "Hai lasciato spazio a quell'auto ferma.", "C\u1eadu \u0111\u00e3 nh\u01b0\u1eddng ch\u1ed7 cho chi\u1ebfc \u00f4 t\u00f4 \u0111ang d\u1eebng." } },
            { "rb-lose-not-the-whole-story/beat/2", new[] { "I would do that again.", "Das w\u00fcrde ich wieder tun.", "Volver\u00eda a hacerlo.", "Je le referais.", "Lo rifarei.", "T\u00f4i v\u1eabn s\u1ebd l\u00e0m v\u1eady l\u1ea7n n\u1eefa." } },
            { "rb-lose-not-the-whole-story/beat/3", new[] { "Then keep that part.", "Dann behalte das bei.", "Pues qu\u00e9date con eso.", "Alors garde \u00e7a.", "Allora tieniti quella parte.", "V\u1eady gi\u1eef l\u1ea5y \u0111i\u1ec1u \u0111\u00f3." } },
            { "rb-lose-not-the-whole-story/beat/4", new[] { "We can fix the rest.", "Den Rest k\u00f6nnen wir verbessern.", "Lo dem\u00e1s lo podemos mejorar.", "On peut corriger le reste.", "Il resto lo possiamo sistemare.", "Ph\u1ea7n c\u00f2n l\u1ea1i m\u00ecnh s\u1eeda \u0111\u01b0\u1ee3c." } },
            { "rb-lose-not-the-whole-story/synopsis", new[] { "A bad placing does not erase one good decision.", "Eine schlechte Platzierung macht eine gute Entscheidung nicht wertlos.", "Un mal puesto no borra una buena decisi\u00f3n.", "Une mauvaise place n'efface pas une bonne d\u00e9cision.", "Un brutto piazzamento non cancella una buona decisione.", "M\u1ed9t th\u1ee9 h\u1ea1ng th\u1ea5p kh\u00f4ng x\u00f3a \u0111i quy\u1ebft \u0111\u1ecbnh \u0111\u00fang." } },
            { "rb-lose-not-the-whole-story/title", new[] { "Not the whole story", "Nicht die ganze Geschichte", "No lo cuenta todo", "Ce n'est pas toute l'histoire", "Non \u00e8 tutta la storia", "Ch\u01b0a ph\u1ea3i to\u00e0n b\u1ed9 c\u00e2u chuy\u1ec7n" } },
            { "rb-lose-one-breath-late/beat/0", new[] { "I saw the gap close.", "Ich habe gesehen, wie die L\u00fccke zuging.", "Vi c\u00f3mo se cerraba el hueco.", "J'ai vu l'espace se refermer.", "Ho visto lo spazio chiudersi.", "T\u00f4i th\u1ea5y kho\u1ea3ng tr\u1ed1ng kh\u00e9p l\u1ea1i." } },
            { "rb-lose-one-breath-late/beat/1", new[] { "One breath too late.", "Einen Atemzug zu sp\u00e4t.", "Un instante demasiado tarde.", "Un souffle trop tard.", "Un respiro troppo tardi.", "Ch\u1eadm m\u1ea5t m\u1ed9t nh\u1ecbp th\u1edf." } },
            { "rb-lose-one-breath-late/beat/2", new[] { "Next time, decide before you arrive.", "Entscheide dich n\u00e4chstes Mal, bevor du dort bist.", "La pr\u00f3xima vez, decide antes de llegar.", "La prochaine fois, d\u00e9cide avant d'arriver.", "La prossima volta decidi prima di arrivare.", "L\u1ea7n sau h\u00e3y quy\u1ebft \u0111\u1ecbnh tr\u01b0\u1edbc khi t\u1edbi \u0111\u00f3." } },
            { "rb-lose-one-breath-late/beat/3", new[] { "I know the feeling now.", "Jetzt kenne ich das Gef\u00fchl.", "Ahora conozco la sensaci\u00f3n.", "Maintenant, je connais cette sensation.", "Ora so che cosa si prova.", "Gi\u1edd t\u00f4i hi\u1ec3u c\u1ea3m gi\u00e1c \u1ea5y r\u1ed3i." } },
            { "rb-lose-one-breath-late/beat/4", new[] { "That is something to take home.", "Das kannst du mit nach Hause nehmen.", "Eso ya es algo que te llevas a casa.", "C'est d\u00e9j\u00e0 quelque chose \u00e0 ramener chez toi.", "\u00c8 gi\u00e0 qualcosa da portare a casa.", "V\u1eady l\u00e0 c\u00f3 \u0111i\u1ec1u \u0111\u1ec3 mang v\u1ec1." } },
            { "rb-lose-one-breath-late/synopsis", new[] { "A small hesitation is accepted and understood.", "Ein kurzes Z\u00f6gern wird akzeptiert und verstanden.", "Una peque\u00f1a vacilaci\u00f3n se acepta y se comprende.", "Une petite h\u00e9sitation est accept\u00e9e et comprise.", "Un attimo di esitazione viene accettato e compreso.", "M\u1ed9t tho\u00e1ng ch\u1ea7n ch\u1eeb \u0111\u01b0\u1ee3c th\u1eeba nh\u1eadn v\u00e0 th\u1ea5u hi\u1ec3u." } },
            { "rb-lose-one-breath-late/title", new[] { "One breath late", "Einen Atemzug zu sp\u00e4t", "Un instante tarde", "Un souffle de retard", "Un respiro in ritardo", "Ch\u1eadm m\u1ed9t nh\u1ecbp th\u1edf" } },
            { "rb-lose-the-empty-boast/beat/0", new[] { "I may have promised too much.", "Vielleicht habe ich zu viel versprochen.", "Quiz\u00e1 he prometido demasiado.", "J'ai peut-\u00eatre promis un peu trop.", "Forse ho promesso troppo.", "C\u00f3 l\u1ebd t\u00f4i \u0111\u00e3 h\u1ee9a h\u01a1i qu\u00e1." } },
            { "rb-lose-the-empty-boast/beat/1", new[] { "Only by an entire finish line.", "Nur eine ganze Ziellinie zu viel.", "Solo te ha faltado una meta entera.", "Seulement une ligne d'arriv\u00e9e enti\u00e8re.", "Solo di un intero traguardo.", "Ch\u1ec9 qu\u00e1 h\u1eb3n m\u1ed9t v\u1ea1ch \u0111\u00edch th\u00f4i." } },
            { "rb-lose-the-empty-boast/beat/2", new[] { "That sounds like me.", "Das klingt nach mir.", "Eso suena muy propio de m\u00ed.", "\u00c7a me ressemble.", "Proprio da me.", "\u0110\u00fang ki\u1ec3u t\u00f4i r\u1ed3i." } },
            { "rb-lose-the-empty-boast/beat/3", new[] { "Try a smaller promise.", "Versprich lieber etwas Kleineres.", "Prueba con una promesa m\u00e1s peque\u00f1a.", "Essaie une promesse plus petite.", "Prova a promettere qualcosa di pi\u00f9 piccolo.", "Th\u1eed h\u1ee9a \u0111i\u1ec1u nh\u1ecf h\u01a1n xem." } },
            { "rb-lose-the-empty-boast/beat/4", new[] { "One cleaner corner.", "Eine Kurve sauberer fahren.", "Una curva m\u00e1s limpia.", "Un virage plus propre.", "Una curva pi\u00f9 pulita.", "M\u1ed9t kh\u00fac cua g\u1ecdn h\u01a1n." } },
            { "rb-lose-the-empty-boast/synopsis", new[] { "A boast turns into a shared laugh and a new start.", "Aus einer Prahlerei werden ein gemeinsames Lachen und ein neuer Anfang.", "Una fanfarronada acaba en risas compartidas y un nuevo comienzo.", "Une vantardise se transforme en rire partag\u00e9 et en nouveau d\u00e9part.", "Una spacconata si trasforma in una risata condivisa e in un nuovo inizio.", "M\u1ed9t c\u00e2u khoe khoang bi\u1ebfn th\u00e0nh ti\u1ebfng c\u01b0\u1eddi chung v\u00e0 m\u1ed9t kh\u1edfi \u0111\u1ea7u m\u1edbi." } },
            { "rb-lose-the-empty-boast/title", new[] { "The empty boast", "Die leere Prahlerei", "Una fanfarronada vac\u00eda", "La promesse en l'air", "Una vanteria vuota", "L\u1eddi kho\u00e1c l\u00e1c tr\u1ed1ng r\u1ed7ng" } },
            { "rb-lose-the-marker/beat/0", new[] { "Which corner?", "Welche Kurve?", "\u00bfQu\u00e9 curva?", "Quel virage ?", "Quale curva?", "Kh\u00fac cua n\u00e0o?" } },
            { "rb-lose-the-marker/beat/1", new[] { "The one by the bent marker.", "Die bei der verbogenen Markierung.", "La del hito torcido.", "Celui pr\u00e8s de la borne tordue.", "Quella vicino al segnale piegato.", "Kh\u00fac c\u1ea1nh c\u1ed9t m\u1ed1c b\u1ecb cong \u1ea5y." } },
            { "rb-lose-the-marker/beat/2", new[] { "I know it.", "Die kenne ich.", "La conozco.", "Je le connais.", "Ho presente.", "T\u00f4i bi\u1ebft ch\u1ed7 \u0111\u00f3." } },
            { "rb-lose-the-marker/beat/3", new[] { "Brake before the shadow next time.", "Brems n\u00e4chstes Mal vor dem Schatten.", "La pr\u00f3xima vez, frena antes de la sombra.", "La prochaine fois, freine avant l'ombre.", "La prossima volta frena prima dell'ombra.", "L\u1ea7n sau phanh tr\u01b0\u1edbc b\u00f3ng r\u00e2m." } },
            { "rb-lose-the-marker/beat/4", new[] { "Before the shadow. Got it.", "Vor dem Schatten. Verstanden.", "Antes de la sombra. Entendido.", "Avant l'ombre. Compris.", "Prima dell'ombra. Capito.", "Tr\u01b0\u1edbc b\u00f3ng r\u00e2m. Nh\u1edb r\u1ed3i." } },
            { "rb-lose-the-marker/synopsis", new[] { "The rider chooses a concrete place to improve.", "Der Fahrer w\u00e4hlt eine konkrete Stelle, an der er sich verbessern will.", "El piloto elige un lugar concreto donde mejorar.", "Le pilote choisit un endroit pr\u00e9cis o\u00f9 progresser.", "Il pilota sceglie un punto preciso su cui migliorare.", "Ng\u01b0\u1eddi l\u00e1i ch\u1ecdn m\u1ed9t ch\u1ed7 c\u1ee5 th\u1ec3 \u0111\u1ec3 c\u1ea3i thi\u1ec7n." } },
            { "rb-lose-the-marker/title", new[] { "The marker", "Die Markierung", "El hito", "La borne", "Il segnale", "C\u1ed9t m\u1ed1c" } },
            { "rb-lose-the-patient-rival/beat/0", new[] { "You could say something.", "Du k\u00f6nntest ruhig etwas sagen.", "Podr\u00edas decir algo.", "Tu pourrais dire quelque chose.", "Potresti dire qualcosa.", "C\u1eadu n\u00f3i g\u00ec \u0111i ch\u1ee9." } },
            { "rb-lose-the-patient-rival/beat/1", new[] { "Your outside line was good.", "Deine Au\u00dfenlinie war gut.", "Tu trazada por fuera era buena.", "Ta trajectoire ext\u00e9rieure \u00e9tait bonne.", "La tua traiettoria esterna era buona.", "\u0110\u01b0\u1eddng \u00f4m cua ngo\u00e0i c\u1ee7a c\u1eadu t\u1ed1t \u0111\u1ea5y." } },
            { "rb-lose-the-patient-rival/beat/2", new[] { "Keep it one second longer.", "Halte sie eine Sekunde l\u00e4nger.", "Mantenla un segundo m\u00e1s.", "Garde-la une seconde de plus.", "Tienila un secondo in pi\u00f9.", "Gi\u1eef th\u00eam m\u1ed9t gi\u00e2y n\u1eefa." } },
            { "rb-lose-the-patient-rival/beat/3", new[] { "That is all?", "Das ist alles?", "\u00bfEso es todo?", "C'est tout ?", "Tutto qui?", "Ch\u1ec9 th\u1ebf th\u00f4i \u00e0?" } },
            { "rb-lose-the-patient-rival/beat/4", new[] { "That is plenty.", "Das ist schon eine Menge.", "Eso es mucho.", "C'est d\u00e9j\u00e0 beaucoup.", "\u00c8 gi\u00e0 molto.", "Th\u1ebf l\u00e0 \u0111\u1ee7 nhi\u1ec1u r\u1ed3i." } },
            { "rb-lose-the-patient-rival/synopsis", new[] { "A rival offers practical advice instead of gloating.", "Statt zu triumphieren, gibt ein Rivale einen praktischen Rat.", "Un rival ofrece consejos pr\u00e1cticos en vez de presumir.", "Un rival donne un conseil pratique au lieu de fanfaronner.", "Un rivale offre un consiglio pratico invece di vantarsi.", "Thay v\u00ec \u0111\u1eafc th\u1eafng, \u0111\u1ed1i th\u1ee7 \u0111\u01b0a ra l\u1eddi khuy\u00ean thi\u1ebft th\u1ef1c." } },
            { "rb-lose-the-patient-rival/title", new[] { "The patient rival", "Der geduldige Rivale", "Un rival paciente", "Le rival patient", "Il rivale paziente", "\u0110\u1ed1i th\u1ee7 ki\u00ean nh\u1eabn" } },
            { "rb-rival-junos-unfinished-map/beat/0", new[] { "Juno is still at the garage after the others leave.", "Juno ist noch in der Garage, als die anderen schon gegangen sind.", "Juno sigue en el garaje cuando los dem\u00e1s ya se han ido.", "Juno reste au garage apr\u00e8s le d\u00e9part des autres.", "Juno \u00e8 ancora al garage quando gli altri se ne sono andati.", "M\u1ecdi ng\u01b0\u1eddi \u0111\u00e3 v\u1ec1, Juno v\u1eabn c\u00f2n \u1edf gara." } },
            { "rb-rival-junos-unfinished-map/beat/1", new[] { "A route card lies beside a cooling engine.", "Neben einem abk\u00fchlenden Motor liegt eine Streckenkarte.", "Una ficha de ruta descansa junto a un motor que se enfr\u00eda.", "Une fiche de route repose pr\u00e8s d'un moteur qui refroidit.", "Una scheda del percorso \u00e8 accanto a un motore che si raffredda.", "T\u1ea5m th\u1ebb l\u1ed9 tr\u00ecnh n\u1eb1m c\u1ea1nh \u0111\u1ed9ng c\u01a1 \u0111ang ngu\u1ed9i." } },
            { "rb-rival-junos-unfinished-map/beat/10", new[] { "The old marker used to be there.", "Die alte Markierung stand dort.", "El antiguo hito estaba ah\u00ed.", "L'ancienne borne \u00e9tait l\u00e0.", "Il vecchio segnale era l\u00ec.", "C\u1ed9t m\u1ed1c c\u0169 t\u1eebng n\u1eb1m \u1edf \u0111\u00f3." } },
            { "rb-rival-junos-unfinished-map/beat/11", new[] { "I learned this road with my brother.", "Mein Bruder hat mir diese Stra\u00dfe gezeigt.", "Aprend\u00ed esta carretera con mi hermano.", "J'ai appris cette route avec mon fr\u00e8re.", "Ho imparato questa strada con mio fratello.", "T\u00f4i h\u1ecdc ch\u1ea1y \u0111\u01b0\u1eddng n\u00e0y c\u00f9ng anh trai." } },
            { "rb-rival-junos-unfinished-map/beat/12", new[] { "He said the corner would make sense one morning.", "Er sagte, eines Morgens w\u00fcrde ich diese Kurve verstehen.", "Dec\u00eda que una ma\u00f1ana entender\u00eda la curva.", "Il disait qu'un matin, je comprendrais ce virage.", "Diceva che una mattina avrei capito quella curva.", "Anh b\u1ea3o r\u1ed3i s\u1ebd c\u00f3 m\u1ed9t bu\u1ed5i s\u00e1ng t\u00f4i hi\u1ec3u kh\u00fac cua \u1ea5y." } },
            { "rb-rival-junos-unfinished-map/beat/13", new[] { "Did it?", "Hast du sie verstanden?", "\u00bfY la entendiste?", "Et alors ?", "\u00c8 successo?", "R\u1ed3i c\u1eadu hi\u1ec3u ch\u01b0a?" } },
            { "rb-rival-junos-unfinished-map/beat/14", new[] { "Not while I was trying to prove him wrong.", "Nicht, solange ich ihm das Gegenteil beweisen wollte.", "No mientras intentaba demostrar que se equivocaba.", "Pas tant que j'essayais de lui donner tort.", "Non finch\u00e9 cercavo di dimostrargli che aveva torto.", "Ch\u01b0a, khi t\u00f4i c\u00f2n c\u1ed1 ch\u1ee9ng minh anh sai." } },
            { "rb-rival-junos-unfinished-map/beat/15", new[] { "They stand above a quiet stretch of water.", "Sie stehen \u00fcber einem stillen St\u00fcck Fluss.", "Se detienen sobre un tramo de agua tranquila.", "Ils s'arr\u00eatent au-dessus d'une \u00e9tendue d'eau calme.", "Si fermano sopra un tratto d'acqua tranquillo.", "H\u1ecd \u0111\u1ee9ng nh\u00ecn xu\u1ed1ng m\u1ed9t \u0111o\u1ea1n s\u00f4ng y\u00ean \u1ea3." } },
            { "rb-rival-junos-unfinished-map/beat/16", new[] { "The exit is visible from here.", "Von hier sieht man den Kurvenausgang.", "Desde aqu\u00ed se ve la salida.", "D'ici, on voit la sortie.", "Da qui si vede l'uscita.", "T\u1eeb \u0111\u00e2y nh\u00ecn th\u1ea5y l\u1ed1i ra cua." } },
            { "rb-rival-junos-unfinished-map/beat/17", new[] { "You cannot see it from the entry.", "Vom Kurveneingang aus nicht.", "Desde la entrada, no.", "On ne la voit pas depuis l'entr\u00e9e.", "Dall'ingresso non la puoi vedere.", "Nh\u01b0ng \u1edf \u0111\u1ea7u cua th\u00ec kh\u00f4ng th\u1ea5y." } },
            { "rb-rival-junos-unfinished-map/beat/18", new[] { "You have to remember it.", "Du musst ihn dir merken.", "Tienes que recordarla.", "Il faut s'en souvenir.", "Devi ricordartela.", "Ph\u1ea3i nh\u1edb n\u00f3 trong \u0111\u1ea7u." } },
            { "rb-rival-junos-unfinished-map/beat/19", new[] { "One more try, then.", "Dann noch ein Versuch.", "Pues un intento m\u00e1s.", "Alors, encore un essai.", "Allora un altro tentativo.", "V\u1eady th\u1eed th\u00eam l\u1ea7n n\u1eefa." } },
            { "rb-rival-junos-unfinished-map/beat/2", new[] { "You never put that card away.", "Du legst diese Karte nie weg.", "Nunca guardas esa ficha.", "Tu ne ranges jamais cette fiche.", "Non metti mai via quella scheda.", "C\u1eadu ch\u1eb3ng bao gi\u1edd c\u1ea5t t\u1ea5m th\u1ebb \u0111\u00f3 \u0111i." } },
            { "rb-rival-junos-unfinished-map/beat/20", new[] { "Juno rolls back to the start of the bend.", "Juno rollt zum Kurveneingang zur\u00fcck.", "Juno vuelve al inicio de la curva.", "Juno revient au d\u00e9but du virage.", "Juno torna all'inizio della curva.", "Juno quay xe v\u1ec1 \u0111\u1ea7u kh\u00fac cua." } },
            { "rb-rival-junos-unfinished-map/beat/21", new[] { "The bike settles before the apex.", "Das Motorrad liegt schon vor dem Scheitelpunkt ruhig.", "La moto se estabiliza antes del v\u00e9rtice.", "La moto se stabilise avant le point de corde.", "La moto si assesta prima del punto di corda.", "Chi\u1ebfc xe \u1ed5n \u0111\u1ecbnh tr\u01b0\u1edbc \u0111\u1ec9nh cua." } },
            { "rb-rival-junos-unfinished-map/beat/22", new[] { "The remembered exit opens at the right moment.", "Der vertraute Kurvenausgang \u00f6ffnet sich im richtigen Moment.", "La salida que recordaba aparece en el momento justo.", "La sortie m\u00e9moris\u00e9e s'ouvre au bon moment.", "L'uscita ricordata si apre al momento giusto.", "L\u1ed1i ra \u0111\u00e3 ghi nh\u1edb hi\u1ec7n l\u00ean \u0111\u00fang l\u00fac." } },
            { "rb-rival-junos-unfinished-map/beat/23", new[] { "No sudden correction. No chase.", "Kein hektisches Gegenlenken. Kein Hinterherjagen.", "Sin correcciones bruscas. Sin persecuci\u00f3n.", "Pas de correction brusque. Pas de poursuite.", "Nessuna correzione improvvisa. Nessun inseguimento.", "Kh\u00f4ng gi\u1eadt m\u00ecnh ch\u1ec9nh h\u01b0\u1edbng. Kh\u00f4ng \u0111u\u1ed5i theo ai." } },
            { "rb-rival-junos-unfinished-map/beat/24", new[] { "That looked different.", "Das sah anders aus.", "Eso ha sido distinto.", "C'\u00e9tait diff\u00e9rent.", "Sembrava diverso.", "L\u1ea7n n\u00e0y tr\u00f4ng kh\u00e1c \u0111\u1ea5y." } },
            { "rb-rival-junos-unfinished-map/beat/25", new[] { "It felt quieter.", "Es f\u00fchlte sich ruhiger an.", "Se ha sentido m\u00e1s tranquilo.", "C'\u00e9tait plus calme.", "Mi \u00e8 sembrato pi\u00f9 tranquillo.", "C\u1ea3m gi\u00e1c nh\u1eb9 nh\u00e0ng h\u01a1n." } },
            { "rb-rival-junos-unfinished-map/beat/26", new[] { "A good morning for that corner.", "Ein guter Morgen f\u00fcr diese Kurve.", "Una buena ma\u00f1ana para esa curva.", "Un beau matin pour ce virage.", "Una bella mattina per quella curva.", "M\u1ed9t bu\u1ed5i s\u00e1ng \u0111\u1eb9p cho kh\u00fac cua \u1ea5y." } },
            { "rb-rival-junos-unfinished-map/beat/27", new[] { "A good morning to bring someone along.", "Ein guter Morgen, um jemanden mitzunehmen.", "Una buena ma\u00f1ana para venir en compa\u00f1\u00eda.", "Un beau matin pour venir en compagnie.", "Una bella mattina per portare qualcuno con s\u00e9.", "M\u1ed9t bu\u1ed5i s\u00e1ng \u0111\u1eb9p \u0111\u1ec3 r\u1ee7 th\u00eam b\u1ea1n." } },
            { "rb-rival-junos-unfinished-map/beat/28", new[] { "The card gains a small, careful mark.", "Auf der Karte kommt eine kleine, sorgf\u00e4ltige Markierung hinzu.", "La ficha recibe una peque\u00f1a marca, hecha con cuidado.", "Une petite marque soign\u00e9e est ajout\u00e9e \u00e0 la fiche.", "Sulla scheda compare un piccolo segno preciso.", "T\u1ea5m th\u1ebb c\u00f3 th\u00eam m\u1ed9t d\u1ea5u nh\u1ecf, n\u1eafn n\u00f3t." } },
            { "rb-rival-junos-unfinished-map/beat/29", new[] { "There are still roads left to learn.", "Es gibt noch Stra\u00dfen zu entdecken.", "A\u00fan quedan carreteras por aprender.", "Il reste encore des routes \u00e0 apprendre.", "Ci sono ancora strade da imparare.", "V\u1eabn c\u00f2n nh\u1eefng con \u0111\u01b0\u1eddng \u0111\u1ec3 h\u1ecdc h\u1ecfi." } },
            { "rb-rival-junos-unfinished-map/beat/3", new[] { "There is one section I never got right.", "Eine Passage habe ich nie richtig hinbekommen.", "Hay un tramo que nunca he hecho bien.", "Il y a un passage que je n'ai jamais bien pris.", "C'\u00e8 un tratto che non mi \u00e8 mai riuscito bene.", "C\u00f3 m\u1ed9t \u0111o\u1ea1n t\u00f4i ch\u01b0a bao gi\u1edd ch\u1ea1y th\u1eadt \u1ed5n." } },
            { "rb-rival-junos-unfinished-map/beat/4", new[] { "Here, where the road doubles back.", "Hier, wo sich die Stra\u00dfe zur\u00fcckwendet.", "Aqu\u00ed, donde la carretera vuelve sobre s\u00ed misma.", "Ici, l\u00e0 o\u00f9 la route revient sur elle-m\u00eame.", "Qui, dove la strada torna indietro.", "\u0110\u00e2y, ch\u1ed7 con \u0111\u01b0\u1eddng ngo\u1eb7t ng\u01b0\u1ee3c l\u1ea1i." } },
            { "rb-rival-junos-unfinished-map/beat/5", new[] { "It looks ordinary on paper.", "Auf dem Papier sieht das ganz gew\u00f6hnlich aus.", "En el papel parece una curva cualquiera.", "Sur le papier, \u00e7a a l'air banal.", "Sulla carta sembra un posto qualsiasi.", "Tr\u00ean gi\u1ea5y tr\u00f4ng b\u00ecnh th\u01b0\u1eddng nh\u1ec9." } },
            { "rb-rival-junos-unfinished-map/beat/6", new[] { "Most important places do.", "Das tun die meisten wichtigen Orte.", "Casi todos los lugares importantes lo parecen.", "Les endroits importants le sont souvent.", "Spesso i posti importanti sembrano cos\u00ec.", "Nh\u1eefng n\u01a1i quan tr\u1ecdng th\u01b0\u1eddng th\u1ebf." } },
            { "rb-rival-junos-unfinished-map/beat/7", new[] { "Will you show me?", "Zeigst du es mir?", "\u00bfMe lo ense\u00f1as?", "Tu me le montres ?", "Me lo fai vedere?", "C\u1eadu ch\u1ec9 t\u00f4i xem \u0111\u01b0\u1ee3c kh\u00f4ng?" } },
            { "rb-rival-junos-unfinished-map/beat/8", new[] { "They follow the river out of town.", "Sie folgen dem Fluss aus der Stadt.", "Siguen el r\u00edo hasta salir del pueblo.", "Ils suivent la rivi\u00e8re en quittant la ville.", "Seguono il fiume fuori citt\u00e0.", "H\u1ecd men theo s\u00f4ng ra kh\u1ecfi th\u1ecb tr\u1ea5n." } },
            { "rb-rival-junos-unfinished-map/beat/9", new[] { "Juno takes the bends without hurry.", "Juno f\u00e4hrt die Kurven ohne Eile.", "Juno toma las curvas sin prisa.", "Juno encha\u00eene les virages sans se presser.", "Juno affronta le curve senza fretta.", "Juno qua nh\u1eefng kh\u00fac cua kh\u00f4ng v\u1ed9i v\u00e3." } },
            { "rb-rival-junos-unfinished-map/synopsis", new[] { "A rider's reputation gives way to the personal reason they return to the road.", "Hinter dem Ruf eines Fahrers zeigt sich der pers\u00f6nliche Grund, immer wieder auf die Stra\u00dfe zur\u00fcckzukehren.", "La reputaci\u00f3n de un piloto deja paso al motivo personal que le hace volver a la carretera.", "La r\u00e9putation d'un pilote s'efface devant la raison personnelle qui le ram\u00e8ne sur la route.", "Dietro la reputazione di un pilota emerge il motivo personale che lo riporta sulla strada.", "\u0110\u1eb1ng sau ti\u1ebfng t\u0103m c\u1ee7a m\u1ed9t tay l\u00e1i l\u00e0 l\u00fd do ri\u00eang khi\u1ebfn ng\u01b0\u1eddi \u1ea5y lu\u00f4n tr\u1edf l\u1ea1i con \u0111\u01b0\u1eddng." } },
