            { "rb-start-cold-hands-warm-engines/synopsis", new[] { "A calm breath precedes the first launch.", "Ein ruhiger Atemzug vor dem ersten Start.", "Una respiraci\u00f3n tranquila precede a la primera salida.", "Une respiration calme pr\u00e9c\u00e8de le premier d\u00e9part.", "Un respiro calmo precede la prima partenza.", "M\u1ed9t h\u01a1i th\u1edf b\u00ecnh t\u0129nh tr\u01b0\u1edbc l\u1ea7n xu\u1ea5t ph\u00e1t \u0111\u1ea7u." } },
            { "rb-start-cold-hands-warm-engines/title", new[] { "Cold hands, warm engines", "Kalte H\u00e4nde, warme Motoren", "Manos fr\u00edas, motores calientes", "Mains froides, moteurs chauds", "Mani fredde, motori caldi", "Tay l\u1ea1nh, m\u00e1y \u1ea5m" } },
            { "rb-start-late-light/beat/0", new[] { "Catch that last light.", "Fang das letzte Licht ein.", "Aprovecha esa \u00faltima luz.", "Profite de cette derni\u00e8re lumi\u00e8re.", "Prendi l'ultima luce.", "\u0110\u00f3n ch\u00fat n\u1eafng cu\u1ed1i c\u00f9ng nh\u00e9." } },
            { "rb-start-late-light/beat/1", new[] { "Keep the sun out of the mirrors.", "Halte die Sonne aus den Spiegeln.", "Que el sol no te d\u00e9 en los retrovisores.", "Garde le soleil hors des r\u00e9tros.", "Tieni il sole fuori dagli specchietti.", "\u0110\u1eebng \u0111\u1ec3 n\u1eafng chi\u1ebfu v\u00e0o g\u01b0\u01a1ng." } },
