            { "rb-start-one-clean-launch/beat/0", new[] { "No hurry in the wrist.", "Keine Hektik am Gasgriff.", "Sin prisas con la mu\u00f1eca.", "Pas de pr\u00e9cipitation dans le poignet.", "Niente fretta nel polso.", "\u0110\u1eebng v\u1ed9i v\u1eb7n ga." } },
