            { "rb-start-one-clean-launch/beat/3", new[] { "Clean and gone.", "Sauber losgefahren.", "Una salida limpia, y en marcha.", "Un d\u00e9part propre, et c'est parti.", "Pulita, e via.", "G\u1ecdn g\u00e0ng, l\u00ean \u0111\u01b0\u1eddng th\u00f4i." } },
            { "rb-start-one-clean-launch/synopsis", new[] { "A rider avoids repeating an earlier stall.", "Der Fahrer vermeidet es, den Motor erneut abzuw\u00fcrgen.", "Un piloto evita que el motor vuelva a calarse.", "Un pilote \u00e9vite de caler comme la fois pr\u00e9c\u00e9dente.", "Un pilota evita di spegnere di nuovo il motore alla partenza.", "Ng\u01b0\u1eddi l\u00e1i tr\u00e1nh l\u1eb7p l\u1ea1i l\u1ea7n ch\u1ebft m\u00e1y tr\u01b0\u1edbc." } },
            { "rb-start-one-clean-launch/title", new[] { "One clean launch", "Ein sauberer Start", "Una salida limpia", "Un d\u00e9part propre", "Una partenza pulita", "M\u1ed9t l\u1ea7n \u0111\u1ec1-pa g\u1ecdn" } },
            { "rb-start-the-quiet-grid/beat/0", new[] { "Last jokes now.", "Jetzt noch die letzten Witze.", "Ahora, las \u00faltimas bromas.", "Les derni\u00e8res blagues, maintenant.", "Ultime battute, adesso.", "\u0110\u00f9a n\u1ed1t b\u00e2y gi\u1edd nh\u00e9." } },
            { "rb-start-the-quiet-grid/beat/1", new[] { "Then listen.", "Danach zuh\u00f6ren.", "Despu\u00e9s, a escuchar.", "Ensuite, on \u00e9coute.", "Poi ascoltate.", "R\u1ed3i l\u1eafng nghe." } },
