            { "rb-start-the-quiet-grid/synopsis", new[] { "A noisy group becomes focused at the signal.", "Eine laute Gruppe konzentriert sich beim Signal.", "Un grupo ruidoso se concentra al o\u00edr la se\u00f1al.", "Un groupe bruyant se concentre au signal.", "Al segnale, un gruppo rumoroso ritrova la concentrazione.", "Nh\u00f3m b\u1ea1n \u1ed3n \u00e0o t\u1eadp trung l\u1ea1i khi c\u00f3 hi\u1ec7u l\u1ec7nh." } },
