            { "rb-start-wind-check/beat/0", new[] { "Wind from the ridge.", "Wind vom H\u00f6henzug.", "Viento desde la cresta.", "Le vent vient de la cr\u00eate.", "Vento dal crinale.", "Gi\u00f3 t\u1eeb ph\u00eda \u0111\u1ed3i." } },
            { "rb-start-wind-check/beat/1", new[] { "Give the outside a little space.", "Lasst au\u00dfen etwas Platz.", "Dejad algo de espacio por fuera.", "Laissez un peu de place \u00e0 l'ext\u00e9rieur.", "Lascia un po' di spazio all'esterno.", "Ch\u1eeba th\u00eam ch\u00fat ch\u1ed7 ph\u00eda ngo\u00e0i." } },
            { "rb-start-wind-check/beat/2", new[] { "We have it.", "Platz ist da.", "Lo tenemos.", "On en a.", "Ci siamo.", "\u0110\u1ee7 r\u1ed3i." } },
            { "rb-start-wind-check/beat/3", new[] { "Go when it opens.", "Fahr, sobald der Weg frei ist.", "Sal cuando se abra.", "Pars quand \u00e7a s'ouvre.", "Vai quando si apre.", "Tho\u00e1ng th\u00ec \u0111i." } },
            { "rb-start-wind-check/synopsis", new[] { "A crosswind changes the riders' starting positions.", "Seitenwind ver\u00e4ndert die Startpositionen der Fahrer.", "El viento lateral cambia la posici\u00f3n de salida de los pilotos.", "Un vent de travers change les positions de d\u00e9part des pilotes.", "Una raffica laterale cambia le posizioni di partenza dei piloti.", "Gi\u00f3 ngang khi\u1ebfn nh\u1eefng ng\u01b0\u1eddi l\u00e1i \u0111\u1ed5i v\u1ecb tr\u00ed xu\u1ea5t ph\u00e1t." } },
