            { "rb-win-a-glove-across-the-gap/beat/0", new[] { "That last bend was yours.", "Die letzte Kurve geh\u00f6rte dir.", "Esa \u00faltima curva era tuya.", "Ce dernier virage \u00e9tait \u00e0 toi.", "L'ultima curva era tua.", "Kh\u00fac cua cu\u1ed1i thu\u1ed9c v\u1ec1 c\u1eadu." } },
            { "rb-win-a-glove-across-the-gap/beat/1", new[] { "You nearly took it back.", "Du h\u00e4ttest sie dir fast zur\u00fcckgeholt.", "Casi me la quitas.", "Tu as failli me le reprendre.", "Quasi me la riprendevi.", "C\u1eadu su\u00fdt gi\u00e0nh l\u1ea1i r\u1ed3i." } },
            { "rb-win-a-glove-across-the-gap/beat/2", new[] { "Next time?", "N\u00e4chstes Mal?", "\u00bfLa pr\u00f3xima vez?", "La prochaine fois ?", "La prossima volta?", "L\u1ea7n sau nh\u00e9?" } },
            { "rb-win-a-glove-across-the-gap/beat/3", new[] { "Next time.", "N\u00e4chstes Mal.", "La pr\u00f3xima vez.", "La prochaine fois.", "La prossima volta.", "L\u1ea7n sau." } },
            { "rb-win-a-glove-across-the-gap/beat/4", new[] { "Today was enough.", "F\u00fcr heute war das genug.", "Por hoy ha sido suficiente.", "Aujourd'hui, c'\u00e9tait assez.", "Per oggi basta cos\u00ec.", "H\u00f4m nay th\u1ebf l\u00e0 \u0111\u1ee7." } },
            { "rb-win-a-glove-across-the-gap/beat/5", new[] { "Let the engines cool.", "Lassen wir die Motoren abk\u00fchlen.", "Dejemos que se enfr\u00eden los motores.", "Laissons les moteurs refroidir.", "Lasciamo raffreddare i motori.", "\u0110\u1ec3 \u0111\u1ed9ng c\u01a1 ngu\u1ed9i \u0111\u00e3." } },
            { "rb-win-a-glove-across-the-gap/synopsis", new[] { "Two close competitors reconcile without a speech.", "Zwei ebenb\u00fcrtige Konkurrenten vers\u00f6hnen sich ohne gro\u00dfe Worte.", "Dos competidores muy igualados se reconcilian sin discursos.", "Deux concurrents tr\u00e8s proches se r\u00e9concilient sans discours.", "Due avversari alla pari si riconciliano senza discorsi.", "Hai \u0111\u1ed1i th\u1ee7 ngang t\u00e0i l\u00e0m h\u00f2a m\u00e0 kh\u00f4ng c\u1ea7n di\u1ec5n v\u0103n." } },
            { "rb-win-a-glove-across-the-gap/title", new[] { "A glove across the gap", "Ein Handschuh \u00fcberbr\u00fcckt den Abstand", "Un guante salva la distancia", "Un gant tendu", "Un guanto teso tra due rivali", "B\u00e0n tay ch\u00eca qua kho\u1ea3ng c\u00e1ch" } },
            { "rb-win-crew-first/beat/0", new[] { "Nice work out there.", "Gute Arbeit da drau\u00dfen.", "Buen trabajo ah\u00ed fuera.", "Beau travail sur la route.", "Bel lavoro l\u00e0 fuori.", "V\u1eeba r\u1ed3i c\u1eadu l\u00e0m t\u1ed1t l\u1eafm." } },
            { "rb-win-crew-first/beat/1", new[] { "Ask who fixed the rear brake.", "Frag lieber, wer die Hinterradbremse repariert hat.", "Preguntad qui\u00e9n arregl\u00f3 el freno trasero.", "Demandez qui a r\u00e9par\u00e9 le frein arri\u00e8re.", "Chiedi chi ha sistemato il freno posteriore.", "H\u1ecfi xem ai \u0111\u00e3 s\u1eeda phanh sau \u1ea5y." } },
            { "rb-win-crew-first/beat/2", new[] { "We only handed you a wrench.", "Wir haben dir nur einen Schraubenschl\u00fcssel gereicht.", "Solo te pasamos una llave.", "On t'a seulement pass\u00e9 une cl\u00e9.", "Ti abbiamo solo passato una chiave inglese.", "Ch\u00fang t\u00f4i ch\u1ec9 \u0111\u01b0a c\u1eadu c\u00e1i c\u1edd l\u00ea th\u00f4i." } },
            { "rb-win-crew-first/beat/3", new[] { "At exactly the right time.", "Genau im richtigen Moment.", "Justo en el momento adecuado.", "Exactement au bon moment.", "Esattamente al momento giusto.", "V\u00e0o \u0111\u00fang l\u00fac nh\u1ea5t." } },
            { "rb-win-crew-first/beat/4", new[] { "That counts.", "Das z\u00e4hlt.", "Eso cuenta.", "\u00c7a compte.", "E questo conta.", "Th\u1ebf c\u0169ng \u0111\u00e1ng k\u1ec3 m\u00e0." } },
            { "rb-win-crew-first/beat/5", new[] { "All right. We will take it.", "Na gut. Das nehmen wir an.", "Est\u00e1 bien. Aceptamos el m\u00e9rito.", "D'accord. On accepte.", "Va bene. Accettiamo i complimenti.", "\u0110\u01b0\u1ee3c r\u1ed3i. B\u1ecdn t\u00f4i nh\u1eadn l\u1eddi khen." } },
            { "rb-win-crew-first/synopsis", new[] { "The rider redirects congratulations to the crew.", "Der Fahrer gibt die Gl\u00fcckw\u00fcnsche an die Crew weiter.", "El piloto dirige las felicitaciones hacia el equipo.", "Le pilote renvoie les f\u00e9licitations \u00e0 l'\u00e9quipe.", "Il pilota gira i complimenti al gruppo che lo ha aiutato.", "Ng\u01b0\u1eddi l\u00e1i d\u00e0nh nh\u1eefng l\u1eddi ch\u00fac m\u1eebng cho c\u1ea3 nh\u00f3m h\u1ed7 tr\u1ee3." } },
            { "rb-win-crew-first/title", new[] { "Crew first", "Die Crew zuerst", "El equipo primero", "L'\u00e9quipe d'abord", "Prima il gruppo", "Nh\u00f3m b\u1ea1n tr\u01b0\u1edbc ti\u00ean" } },
            { "rb-win-room-at-the-front/beat/0", new[] { "There is the line.", "Da ist die Ziellinie.", "Ah\u00ed est\u00e1 la l\u00ednea.", "Voil\u00e0 la ligne.", "Ecco la linea.", "V\u1ea1ch \u0111\u00edch kia r\u1ed3i." } },
            { "rb-win-room-at-the-front/beat/1", new[] { "We made it.", "Wir haben es geschafft.", "Lo hemos conseguido.", "On y est.", "Ce l'abbiamo fatta.", "M\u00ecnh l\u00e0m \u0111\u01b0\u1ee3c r\u1ed3i." } },
            { "rb-win-room-at-the-front/beat/2", new[] { "Keep the finish clear.", "Haltet den Zielbereich frei.", "Dejad libre la meta.", "Laissez l'arriv\u00e9e d\u00e9gag\u00e9e.", "Lasciate libero il traguardo.", "Gi\u1eef v\u1ea1ch \u0111\u00edch th\u00f4ng tho\u00e1ng nh\u00e9." } },
            { "rb-win-room-at-the-front/beat/3", new[] { "Bring everyone through.", "Lasst alle durchkommen.", "Que pasen todos.", "Faites passer tout le monde.", "Fate passare tutti.", "\u0110\u1ec3 m\u1ecdi ng\u01b0\u1eddi qua h\u1ebft." } },
            { "rb-win-room-at-the-front/beat/4", new[] { "Good run. Every one of you.", "Gut gefahren. Ihr alle.", "Buena carrera. Por parte de todos.", "Belle course. Pour chacun de vous.", "Bella corsa. Per ognuno di voi.", "Ai c\u0169ng ch\u1ea1y t\u1ed1t l\u1eafm." } },
            { "rb-win-room-at-the-front/beat/5", new[] { "There is room for all of us here.", "Hier ist Platz f\u00fcr uns alle.", "Aqu\u00ed hay sitio para todos.", "Il y a de la place pour nous tous ici.", "Qui c'\u00e8 posto per tutti noi.", "\u1ede \u0111\u00e2y c\u00f3 ch\u1ed7 cho t\u1ea5t c\u1ea3 ch\u00fang ta." } },
            { "rb-win-room-at-the-front/synopsis", new[] { "The winner makes room for the rest of the group.", "Der Sieger macht Platz f\u00fcr den Rest der Gruppe.", "Quien gana deja espacio al resto del grupo.", "Le vainqueur laisse de la place au reste du groupe.", "Il vincitore fa posto al resto del gruppo.", "Ng\u01b0\u1eddi th\u1eafng ch\u1eeba ch\u1ed7 cho nh\u1eefng ng\u01b0\u1eddi c\u00f2n l\u1ea1i trong nh\u00f3m." } },
            { "rb-win-room-at-the-front/title", new[] { "Room at the front", "Platz an der Spitze", "Sitio delante", "De la place devant", "Spazio davanti", "Ch\u1ed7 tr\u1ed1ng ph\u00eda tr\u01b0\u1edbc" } },
            { "rb-win-the-line-nobody-saw/beat/0", new[] { "Where did you find that exit?", "Wo hast du diesen Kurvenausgang gefunden?", "\u00bfDe d\u00f3nde has sacado esa salida?", "O\u00f9 as-tu trouv\u00e9 cette sortie ?", "Dove hai trovato quell'uscita?", "C\u1eadu t\u00ecm \u0111\u01b0\u1ee3c l\u1ed1i ra \u0111\u00f3 \u1edf \u0111\u00e2u?" } },
            { "rb-win-the-line-nobody-saw/beat/1", new[] { "I stopped staring at your rear wheel.", "Ich habe aufgeh\u00f6rt, auf dein Hinterrad zu starren.", "He dejado de mirar tu rueda trasera.", "J'ai arr\u00eat\u00e9 de fixer ta roue arri\u00e8re.", "Ho smesso di fissare la tua ruota posteriore.", "T\u00f4i th\u00f4i nh\u00ecn ch\u1eb1m ch\u1eb1m b\u00e1nh sau c\u1ee7a c\u1eadu." } },
            { "rb-win-the-line-nobody-saw/beat/2", new[] { "The opening was right there.", "Die L\u00fccke war direkt da.", "El hueco estaba ah\u00ed mismo.", "L'ouverture \u00e9tait juste l\u00e0.", "Il varco era proprio l\u00ec.", "Kho\u1ea3ng tr\u1ed1ng n\u1eb1m ngay \u0111\u00f3 m\u00e0." } },
            { "rb-win-the-line-nobody-saw/beat/3", new[] { "I was saving that lesson.", "Diese Lektion wollte ich noch f\u00fcr mich behalten.", "Me estaba guardando esa lecci\u00f3n.", "Je gardais cette le\u00e7on pour moi.", "Mi tenevo quella lezione per dopo.", "T\u00f4i \u0111ang \u0111\u1ec3 d\u00e0nh b\u00e0i h\u1ecdc \u1ea5y." } },
            { "rb-win-the-line-nobody-saw/beat/4", new[] { "Then consider it borrowed.", "Dann betrachte sie als ausgeliehen.", "Pues consid\u00e9rala prestada.", "Alors consid\u00e8re-la comme emprunt\u00e9e.", "Allora considerala in prestito.", "V\u1eady coi nh\u01b0 t\u00f4i m\u01b0\u1ee3n nh\u00e9." } },
            { "rb-win-the-line-nobody-saw/beat/5", new[] { "Bring it back next race.", "Gib sie mir beim n\u00e4chsten Rennen zur\u00fcck.", "Devu\u00e9lvemela en la pr\u00f3xima carrera.", "Rends-la-moi \u00e0 la prochaine course.", "Restituiscila alla prossima gara.", "Cu\u1ed9c \u0111ua t\u1edbi nh\u1edb tr\u1ea3 l\u1ea1i." } },
            { "rb-win-the-line-nobody-saw/synopsis", new[] { "A clever late line becomes the subject of a friendly debate.", "Eine geschickt sp\u00e4t gew\u00e4hlte Linie wird zum Thema einer freundlichen Diskussion.", "Una ingeniosa trazada de \u00faltima hora da pie a un debate amistoso.", "Une trajectoire tardive et astucieuse devient le sujet d'un d\u00e9bat amical.", "Una traiettoria astuta nel finale diventa argomento di una discussione amichevole.", "M\u1ed9t \u0111\u01b0\u1eddng ch\u1ea1y kh\u00f4n kh\u00e9o \u1edf cu\u1ed1i cu\u1ed9c \u0111ua m\u1edf \u0111\u1ea7u cu\u1ed9c tranh lu\u1eadn th\u00e2n thi\u1ec7n." } },
            { "rb-win-the-line-nobody-saw/title", new[] { "The line nobody saw", "Die Linie, die keiner sah", "La trazada que nadie vio", "La trajectoire que personne n'a vue", "La traiettoria che nessuno aveva visto", "\u0110\u01b0\u1eddng ch\u1ea1y kh\u00f4ng ai th\u1ea5y" } },
            { "rb-win-the-long-way-pays/beat/0", new[] { "You stayed outside the whole way.", "Du bist die ganze Zeit au\u00dfen geblieben.", "Has ido por fuera todo el tiempo.", "Tu es rest\u00e9 \u00e0 l'ext\u00e9rieur tout du long.", "Sei rimasto all'esterno per tutto il tempo.", "C\u1eadu b\u00e1m ph\u00eda ngo\u00e0i su\u1ed1t c\u1ea3 \u0111o\u1ea1n." } },
            { "rb-win-the-long-way-pays/beat/1", new[] { "There was more room to breathe.", "Da war mehr Luft zum Atmen.", "Hab\u00eda m\u00e1s espacio para respirar.", "Il y avait plus de place pour respirer.", "C'era pi\u00f9 spazio per respirare.", "\u1ede \u0111\u00f3 c\u00f3 th\u00eam ch\u1ed7 \u0111\u1ec3 th\u1edf." } },
            { "rb-win-the-long-way-pays/beat/2", new[] { "More road, too.", "Und mehr Stra\u00dfe.", "Y m\u00e1s carretera.", "Et plus de route aussi.", "Anche pi\u00f9 strada.", "C\u0169ng th\u00eam \u0111\u01b0\u1eddng \u0111\u1ec3 ch\u1ea1y n\u1eefa." } },
            { "rb-win-the-long-way-pays/beat/3", new[] { "Sometimes the long line is the clean one.", "Manchmal ist die lange Linie die saubere.", "A veces, la trazada larga es la m\u00e1s limpia.", "Parfois, la trajectoire longue est la plus propre.", "A volte la traiettoria lunga \u00e8 quella pulita.", "\u0110\u00f4i khi \u0111\u01b0\u1eddng d\u00e0i l\u1ea1i l\u00e0 \u0111\u01b0\u1eddng g\u1ecdn nh\u1ea5t." } },
            { "rb-win-the-long-way-pays/beat/4", new[] { "I will remember that.", "Das merke ich mir.", "Lo recordar\u00e9.", "Je m'en souviendrai.", "Me lo ricorder\u00f2.", "T\u00f4i s\u1ebd nh\u1edb \u0111i\u1ec1u \u0111\u00f3." } },
            { "rb-win-the-long-way-pays/beat/5", new[] { "Then it was a good race for both of us.", "Dann war es f\u00fcr uns beide ein gutes Rennen.", "Entonces ha sido una buena carrera para los dos.", "Alors c'\u00e9tait une bonne course pour nous deux.", "Allora \u00e8 stata una buona gara per entrambi.", "V\u1eady l\u00e0 c\u1ea3 hai \u0111\u1ec1u c\u00f3 m\u1ed9t cu\u1ed9c \u0111ua t\u1ed1t." } },
            { "rb-win-the-long-way-pays/synopsis", new[] { "Patience and an outside pass earn a celebration.", "Geduld und ein \u00dcberholman\u00f6ver au\u00dfen sind ein Grund zum Feiern.", "La paciencia y un adelantamiento por fuera merecen una celebraci\u00f3n.", "La patience et un d\u00e9passement par l'ext\u00e9rieur m\u00e9ritent une f\u00eate.", "La pazienza e un sorpasso all'esterno meritano una festa.", "Ki\u00ean nh\u1eabn v\u00e0 m\u1ed9t pha v\u01b0\u1ee3t ph\u00eda ngo\u00e0i \u0111em l\u1ea1i ni\u1ec1m vui chi\u1ebfn th\u1eafng." } },
            { "rb-win-the-long-way-pays/title", new[] { "The long way pays", "Der lange Weg lohnt sich", "El camino largo da resultado", "Le chemin long paie", "La strada lunga ripaga", "\u0110\u01b0\u1eddng d\u00e0i \u0111\u01b0\u1ee3c \u0111\u1ec1n \u0111\u00e1p" } },
            { "rb-win-the-small-victory/beat/0", new[] { "You came in wide. Everything all right?", "Du bist weit au\u00dfen reingekommen. Alles in Ordnung?", "Has entrado abierto. \u00bfTodo bien?", "Tu es arriv\u00e9 large. Tout va bien ?", "Sei entrato largo. Tutto a posto?", "C\u1eadu v\u00e0o cua r\u1ed9ng qu\u00e1. M\u1ecdi th\u1ee9 \u1ed5n ch\u1ee9?" } },
            { "rb-win-the-small-victory/beat/1", new[] { "All right. Just out of road.", "Alles gut. Nur die Stra\u00dfe war zu Ende.", "Todo bien. Solo me he quedado sin carretera.", "\u00c7a va. Il me manquait juste un peu de route.", "Tutto a posto. Era finita la strada.", "\u1ed4n. Ch\u1ec9 l\u00e0 h\u1ebft ch\u1ed7 \u0111\u1ec3 ch\u1ea1y th\u00f4i." } },
            { "rb-win-the-small-victory/beat/2", new[] { "There will be another one.", "Es gibt noch ein Rennen.", "Habr\u00e1 otra.", "Il y en aura une autre.", "Ci sar\u00e0 un'altra gara.", "R\u1ed3i s\u1ebd c\u00f3 cu\u1ed9c \u0111ua kh\u00e1c." } },
            { "rb-win-the-small-victory/beat/3", new[] { "And another chance to catch you.", "Und noch eine Chance, dich einzuholen.", "Y otra oportunidad de alcanzarte.", "Et une autre chance de te rattraper.", "E un'altra occasione per raggiungerti.", "V\u00e0 c\u01a1 h\u1ed9i kh\u00e1c \u0111\u1ec3 \u0111u\u1ed5i k\u1ecbp c\u1eadu." } },
            { "rb-win-the-small-victory/beat/4", new[] { "I look forward to it.", "Darauf freue ich mich.", "La espero con ganas.", "J'ai h\u00e2te.", "Non vedo l'ora.", "T\u00f4i mong t\u1edbi l\u00fac \u0111\u00f3." } },
            { "rb-win-the-small-victory/beat/5", new[] { "One good finish at a time.", "Ein guter Zieleinlauf nach dem anderen.", "Una buena llegada cada vez.", "Une belle arriv\u00e9e \u00e0 la fois.", "Un buon arrivo alla volta.", "C\u1ee9 t\u1eebng l\u1ea7n v\u1ec1 \u0111\u00edch th\u1eadt t\u1ed1t." } },
            { "rb-win-the-small-victory/synopsis", new[] { "The winner quietly checks on a rival before celebrating.", "Der Sieger fragt zuerst leise nach seinem Rivalen, bevor er feiert.", "Quien gana se interesa discretamente por su rival antes de celebrarlo.", "Le vainqueur prend discr\u00e8tement des nouvelles d'un rival avant de f\u00eater sa victoire.", "Prima di festeggiare, il vincitore si assicura con discrezione che il rivale stia bene.", "Tr\u01b0\u1edbc khi \u0103n m\u1eebng, ng\u01b0\u1eddi th\u1eafng l\u1eb7ng l\u1ebd h\u1ecfi th\u0103m \u0111\u1ed1i th\u1ee7." } },
            { "rb-win-the-small-victory/title", new[] { "The small victory", "Der kleine Sieg", "La peque\u00f1a victoria", "La petite victoire", "La piccola vittoria", "Chi\u1ebfn th\u1eafng nh\u1ecf" } },
            { "rb-wreck-a-careful-lift/beat/0", new[] { "That is enough road for today.", "Genug Stra\u00dfe f\u00fcr heute.", "Por hoy, ya hemos tenido bastante carretera.", "Assez de route pour aujourd'hui.", "Per oggi hai fatto abbastanza strada.", "H\u00f4m nay ch\u1ea1y v\u1eady \u0111\u1ee7 r\u1ed3i." } },
            { "rb-wreck-a-careful-lift/beat/1", new[] { "Can you stand?", "Kannst du aufstehen?", "\u00bfPuedes ponerte de pie?", "Tu peux te lever ?", "Riesci ad alzarti?", "C\u1eadu \u0111\u1ee9ng \u0111\u01b0\u1ee3c kh\u00f4ng?" } },
            { "rb-wreck-a-careful-lift/beat/2", new[] { "Slowly.", "Langsam.", "Despacio.", "Doucement.", "Piano.", "T\u1eeb t\u1eeb th\u00f4i." } },
            { "rb-wreck-a-careful-lift/beat/3", new[] { "One at the bars. One at the rear.", "Einer am Lenker. Einer am Heck.", "Uno al manillar. Otro atr\u00e1s.", "Un au guidon. Un \u00e0 l'arri\u00e8re.", "Uno al manubrio. Uno dietro.", "M\u1ed9t ng\u01b0\u1eddi gi\u1eef tay l\u00e1i. M\u1ed9t ng\u01b0\u1eddi \u1edf \u0111u\u00f4i xe." } },
            { "rb-wreck-a-careful-lift/beat/4", new[] { "On three, together.", "Auf drei, gemeinsam.", "A la de tres, juntos.", "\u00c0 trois, ensemble.", "Al tre, insieme.", "\u0110\u1ebfm t\u1edbi ba r\u1ed3i c\u00f9ng n\u00e2ng." } },
            { "rb-wreck-a-careful-lift/beat/5", new[] { "There. Nobody has to prove anything.", "So. Niemand muss hier etwas beweisen.", "Ya est\u00e1. Nadie tiene que demostrar nada.", "Voil\u00e0. Personne n'a rien \u00e0 prouver.", "Ecco. Nessuno deve dimostrare niente.", "\u0110\u01b0\u1ee3c r\u1ed3i. Kh\u00f4ng ai ph\u1ea3i ch\u1ee9ng t\u1ecf g\u00ec c\u1ea3." } },
            { "rb-wreck-a-careful-lift/beat/6", new[] { "Call it a ride home.", "Nennen wir es eine Heimfahrt.", "Llam\u00e9moslo una vuelta a casa.", "Disons qu'on rentre \u00e0 la maison.", "Chiamiamolo un ritorno a casa.", "Gi\u1edd coi nh\u01b0 m\u1ed9t chuy\u1ebfn v\u1ec1 nh\u00e0." } },
            { "rb-wreck-a-careful-lift/synopsis", new[] { "The group coordinates a safe recovery.", "Die Gruppe stimmt sich ab, um das Motorrad sicher zu bergen.", "El grupo se coordina para recuperar la moto con seguridad.", "Le groupe se coordonne pour relever la moto en s\u00e9curit\u00e9.", "Il gruppo si coordina per recuperare la moto in sicurezza.", "C\u1ea3 nh\u00f3m ph\u1ed1i h\u1ee3p \u0111\u1ec3 thu d\u1ecdn an to\u00e0n." } },
            { "rb-wreck-a-careful-lift/title", new[] { "A careful lift", "Vorsichtig aufrichten", "Levantar con cuidado", "Relever avec pr\u00e9caution", "Sollevare con cura", "C\u00f9ng n\u00e2ng xe c\u1ea9n th\u1eadn" } },
            { "rb-wreck-a-clean-way-out/beat/0", new[] { "Someone is coming.", "Da kommt jemand.", "Viene alguien.", "Quelqu'un arrive.", "Sta arrivando qualcuno.", "C\u00f3 ng\u01b0\u1eddi \u0111ang t\u1edbi." } },
            { "rb-wreck-a-clean-way-out/beat/1", new[] { "Leave the machine for a moment.", "Lass die Maschine kurz liegen.", "Deja la moto un momento.", "Laisse la machine un instant.", "Lascia la moto per un momento.", "T\u1ea1m \u0111\u1ec3 xe \u0111\u00f3 \u0111\u00e3." } },
            { "rb-wreck-a-clean-way-out/beat/2", new[] { "Behind the barrier.", "Hinter die Leitplanke.", "Detr\u00e1s de la barrera.", "Derri\u00e8re la barri\u00e8re.", "Dietro la barriera.", "V\u00e0o sau r\u00e0o ch\u1eafn." } },
            { "rb-wreck-a-clean-way-out/beat/3", new[] { "We are clear.", "Wir sind in Sicherheit.", "Estamos fuera de peligro.", "Nous sommes \u00e0 l'abri.", "Siamo fuori dalla strada.", "M\u00ecnh ra kh\u1ecfi \u0111\u01b0\u1eddng r\u1ed3i." } },
            { "rb-wreck-a-clean-way-out/beat/4", new[] { "Now we can plan.", "Jetzt k\u00f6nnen wir planen.", "Ahora podemos hacer planes.", "Maintenant, on peut r\u00e9fl\u00e9chir.", "Ora possiamo fare un piano.", "Gi\u1edd c\u00f3 th\u1ec3 t\u00ednh ti\u1ebfp." } },
            { "rb-wreck-a-clean-way-out/synopsis", new[] { "The rider prioritizes clearing the road.", "Der Fahrer k\u00fcmmert sich zuerst darum, die Stra\u00dfe freizumachen.", "El piloto da prioridad a dejar libre la carretera.", "Le pilote donne la priorit\u00e9 au d\u00e9gagement de la route.", "Il pilota pensa prima a liberare la strada.", "Ng\u01b0\u1eddi l\u00e1i \u01b0u ti\u00ean r\u1eddi kh\u1ecfi l\u00f2ng \u0111\u01b0\u1eddng." } },
            { "rb-wreck-a-clean-way-out/title", new[] { "A clean way out", "Sicher hinaus", "Una salida despejada", "Une sortie d\u00e9gag\u00e9e", "Un'uscita sicura", "M\u1ed9t l\u1ed1i ra an to\u00e0n" } },
            { "rb-wreck-count-the-important-parts/beat/0", new[] { "Easy. Stay still for a moment.", "Ganz ruhig. Bleib einen Moment still.", "Tranquilo. No te muevas un momento.", "Doucement. Ne bouge pas un instant.", "Calma. Non muoverti per un momento.", "B\u00ecnh t\u0129nh. Gi\u1eef y\u00ean ng\u01b0\u1eddi m\u1ed9t l\u00e1t." } },
            { "rb-wreck-count-the-important-parts/beat/1", new[] { "Hands. Knees. Breath.", "H\u00e4nde. Knie. Atmung.", "Manos. Rodillas. Respiraci\u00f3n.", "Mains. Genoux. Souffle.", "Mani. Ginocchia. Respiro.", "Tay. G\u1ed1i. H\u01a1i th\u1edf." } },
            { "rb-wreck-count-the-important-parts/beat/2", new[] { "All accounted for.", "Alles noch da.", "Todo en su sitio.", "Tout est l\u00e0.", "C'\u00e8 tutto.", "\u0110\u1ec1u \u1ed5n c\u1ea3." } },
            { "rb-wreck-count-the-important-parts/beat/3", new[] { "Then we can look at the bike.", "Dann k\u00f6nnen wir uns das Motorrad ansehen.", "Entonces ya podemos mirar la moto.", "Alors on peut regarder la moto.", "Poi possiamo guardare la moto.", "Gi\u1edd m\u00ecnh xem chi\u1ebfc xe \u0111\u01b0\u1ee3c r\u1ed3i." } },
            { "rb-wreck-count-the-important-parts/beat/4", new[] { "In that order.", "In dieser Reihenfolge.", "En ese orden.", "Dans cet ordre.", "In quest'ordine.", "Ph\u1ea3i theo \u0111\u00fang th\u1ee9 t\u1ef1 \u1ea5y." } },
            { "rb-wreck-count-the-important-parts/synopsis", new[] { "The rider checks themselves before the machine.", "Nach dem Sturz z\u00e4hlt zuerst der eigene Zustand, dann der der Maschine.", "El piloto comprueba su propio estado antes que el de la moto.", "Le pilote v\u00e9rifie son propre \u00e9tat avant celui de la machine.", "Il pilota controlla prima s\u00e9 stesso e poi la moto.", "Ng\u01b0\u1eddi l\u00e1i ki\u1ec3m tra b\u1ea3n th\u00e2n tr\u01b0\u1edbc khi xem x\u00e9t chi\u1ebfc xe." } },
            { "rb-wreck-count-the-important-parts/title", new[] { "Count the important parts", "Auf die wichtigen Teile achten", "Cuenta lo importante", "Compter l'essentiel", "Contare le cose importanti", "Ki\u1ec3m tra nh\u1eefng ph\u1ea7n quan tr\u1ecdng" } },
            { "rb-wreck-listen-to-the-silence/beat/0", new[] { "I heard it before I felt it.", "Ich habe es geh\u00f6rt, bevor ich es gesp\u00fcrt habe.", "Lo o\u00ed antes de sentirlo.", "Je l'ai entendu avant de le sentir.", "L'ho sentito prima con le orecchie che col corpo.", "T\u00f4i nghe th\u1ea5y tr\u01b0\u1edbc khi c\u1ea3m th\u1ea5y." } },
            { "rb-wreck-listen-to-the-silence/beat/1", new[] { "Then the next warning is worth hearing.", "Dann lohnt es sich, auf die n\u00e4chste Warnung zu h\u00f6ren.", "Entonces merece la pena escuchar el pr\u00f3ximo aviso.", "Alors le prochain avertissement m\u00e9rite d'\u00eatre \u00e9cout\u00e9.", "Allora il prossimo avvertimento merita ascolto.", "V\u1eady l\u1ea7n sau h\u00e3y l\u1eafng nghe l\u1eddi c\u1ea3nh b\u00e1o." } },
            { "rb-wreck-listen-to-the-silence/beat/2", new[] { "That wheel is done.", "Das Rad ist hin\u00fcber.", "Esa rueda no da para m\u00e1s.", "Cette roue ne peut plus rouler.", "Quella ruota \u00e8 andata.", "B\u00e1nh \u0111\u00f3 h\u1ecfng h\u1eb3n r\u1ed3i." } },
            { "rb-wreck-listen-to-the-silence/beat/3", new[] { "So is the race.", "Das Rennen auch.", "La carrera tampoco.", "La course est finie aussi.", "Anche la gara.", "Cu\u1ed9c \u0111ua c\u0169ng k\u1ebft th\u00fac r\u1ed3i." } },
            { "rb-wreck-listen-to-the-silence/beat/4", new[] { "Not the rider.", "Der Fahrer nicht.", "El piloto s\u00ed.", "Pas le pilote.", "Ma non il pilota.", "Nh\u01b0ng ng\u01b0\u1eddi l\u00e1i th\u00ec ch\u01b0a." } },
            { "rb-wreck-listen-to-the-silence/beat/5", new[] { "That is the part we keep.", "Darauf kommt es an.", "Eso es lo que conservamos.", "C'est \u00e7a qu'on garde.", "\u00c8 quella la parte da salvare.", "\u0110\u00f3 m\u1edbi l\u00e0 ph\u1ea7n c\u1ea7n gi\u1eef." } },
            { "rb-wreck-listen-to-the-silence/synopsis", new[] { "The stopped engine gives space for an honest assessment.", "Der verstummte Motor schafft Raum f\u00fcr eine ehrliche Einsch\u00e4tzung.", "El motor parado deja espacio para valorar lo ocurrido con sinceridad.", "Le moteur arr\u00eat\u00e9 laisse place \u00e0 un bilan sinc\u00e8re.", "Il motore spento lascia spazio a una valutazione sincera.", "\u0110\u1ed9ng c\u01a1 ng\u1eebng l\u1ea1i, nh\u01b0\u1eddng ch\u1ed7 cho m\u1ed9t \u0111\u00e1nh gi\u00e1 th\u1eb3ng th\u1eafn." } },
            { "rb-wreck-listen-to-the-silence/title", new[] { "Listen to the silence", "Auf die Stille h\u00f6ren", "Escucha el silencio", "\u00c9couter le silence", "Ascoltare il silenzio", "L\u1eafng nghe y\u00ean l\u1eb7ng" } },
            { "rb-wreck-the-missing-hurry/beat/0", new[] { "Go. You will lose the light.", "Fahr. Sonst wird es dunkel.", "Vete. Se te va a ir la luz.", "Vas-y. Tu vas perdre la lumi\u00e8re.", "Vai. Perderai la luce.", "\u0110i \u0111i. S\u1eafp h\u1ebft \u00e1nh s\u00e1ng r\u1ed3i." } },
            { "rb-wreck-the-missing-hurry/beat/1", new[] { "The light can wait.", "Das Licht kann warten.", "La luz puede esperar.", "La lumi\u00e8re peut attendre.", "La luce pu\u00f2 aspettare.", "\u00c1nh s\u00e1ng ch\u1edd \u0111\u01b0\u1ee3c." } },
            { "rb-wreck-the-missing-hurry/beat/2", new[] { "The finish cannot.", "Das Ziel nicht.", "La meta, no.", "Pas l'arriv\u00e9e.", "Il traguardo no.", "V\u1ea1ch \u0111\u00edch th\u00ec kh\u00f4ng." } },
            { "rb-wreck-the-missing-hurry/beat/3", new[] { "Today it can.", "Heute schon.", "Hoy s\u00ed.", "Aujourd'hui, si.", "Oggi s\u00ec.", "H\u00f4m nay th\u00ec \u0111\u01b0\u1ee3c." } },
            { "rb-wreck-the-missing-hurry/beat/4", new[] { "Come on. Shoulder first.", "Komm. Erst auf den Seitenstreifen.", "Vamos. Primero, al arc\u00e9n.", "Allez. D'abord, le bas-c\u00f4t\u00e9.", "Forza. Prima sulla banchina.", "N\u00e0o. V\u00e0o l\u1ec1 tr\u01b0\u1edbc \u0111\u00e3." } },
            { "rb-wreck-the-missing-hurry/synopsis", new[] { "A rival refuses to rush a stranded rider.", "Ein Rivale l\u00e4sst einen liegen gebliebenen Fahrer nicht hetzen.", "Un rival se niega a meter prisa a un piloto que se ha quedado tirado.", "Un rival refuse de presser un pilote immobilis\u00e9.", "Un rivale si rifiuta di mettere fretta a chi \u00e8 rimasto bloccato.", "\u0110\u1ed1i th\u1ee7 nh\u1ea5t quy\u1ebft kh\u00f4ng gi\u1ee5c ng\u01b0\u1eddi \u0111ang m\u1eafc k\u1eb9t b\u00ean \u0111\u01b0\u1eddng." } },
            { "rb-wreck-the-missing-hurry/title", new[] { "The missing hurry", "Die verlorene Eile", "Las prisas que faltan", "L'urgence disparue", "La fretta che non c'\u00e8", "Kh\u00f4ng c\u00f2n v\u1ed9i v\u00e3" } },
            { "rb-wreck-tomorrows-repair/beat/0", new[] { "That will need a long evening.", "Das wird ein langer Abend.", "Eso nos va a llevar una tarde larga.", "\u00c7a va nous prendre une longue soir\u00e9e.", "Ci vorr\u00e0 una lunga serata.", "Ch\u1eafc ph\u1ea3i m\u1ea5t c\u1ea3 bu\u1ed5i t\u1ed1i d\u00e0i." } },
            { "rb-wreck-tomorrows-repair/beat/1", new[] { "Bars, brake, and a little patience.", "Lenker, Bremse und etwas Geduld.", "Manillar, freno y un poco de paciencia.", "Le guidon, le frein et un peu de patience.", "Manubrio, freno e un po' di pazienza.", "Tay l\u00e1i, phanh v\u00e0 m\u1ed9t ch\u00fat ki\u00ean nh\u1eabn." } },
            { "rb-wreck-tomorrows-repair/beat/2", new[] { "Start with the brake.", "Fang mit der Bremse an.", "Empieza por el freno.", "Commence par le frein.", "Cominciamo dal freno.", "B\u1eaft \u0111\u1ea7u v\u1edbi phanh nh\u00e9." } },
            { "rb-wreck-tomorrows-repair/beat/3", new[] { "I will bring the lamp.", "Ich bringe die Lampe mit.", "Yo traer\u00e9 la l\u00e1mpara.", "J'apporterai la lampe.", "Porter\u00f2 la lampada.", "T\u00f4i s\u1ebd mang \u0111\u00e8n t\u1edbi." } },
            { "rb-wreck-tomorrows-repair/beat/4", new[] { "Then we have a plan.", "Dann haben wir einen Plan.", "Entonces ya tenemos un plan.", "Alors on a un plan.", "Allora abbiamo un piano.", "V\u1eady l\u00e0 c\u00f3 k\u1ebf ho\u1ea1ch r\u1ed3i." } },
